_FIXED_OR_OBSOLETE_OUTPUT_COLUMNS = {
    "candidate_parallel_mode",
    "freq_threshold",
    "numeric_rows",
    "optim_bootstrap_time",
    "proxy_eval_mode",
    # (2026-07-05) candidate-search metrics consolidation: these are pure
    # aliases of other still-exposed columns in every backend --
    # unique_index_candidates == valid_index_candidates always (both
    # increment together at the same site in every scan implementation);
    # after_coord == valid_index_candidates always; partial_checks ==
    # after_coord always (once VPTree's now-fixed per-node-visit overload of
    # partial_checks is excluded -- see docs/implementation_log.md). Dropping
    # them here (not by editing the column tuples directly) keeps
    # _RAW_*_COLUMNS/_filter_comparison_row's positional zip correct.
    "candidate_search_unique_index_candidates",
    "candidate_search_after_coord",
    "candidate_search_partial_checks",
    "proxy_search_unique_index_candidates",
    "proxy_search_after_coord",
    "proxy_search_partial_checks",
    # (2026-07-05) vptree/angular_lsh/dynamic_graph_ann backends removed at
    # the human's request (kept: sorted_arrays_bs, bptree). These params were
    # only ever read by those three dropped backends -- dropped from CSV
    # output the same safe way as above (constructors/record-builders still
    # accept and default them internally, unused in practice now that those
    # backends can no longer be selected -- see docs/implementation_log.md,
    # "backend removal: blocked_lazy/vptree/angular_lsh/dynamic_graph_ann").
    "candidate_lsh_radius",
    "candidate_ann_m",
    "candidate_ann_z",
    "candidate_ann_ef",
}


def _drop_fixed_or_obsolete_output_columns(columns: Sequence[str]) -> Sequence[str]:
    return tuple(
        col for col in columns
        if (
            col not in _FIXED_OR_OBSOLETE_OUTPUT_COLUMNS
            and not col.startswith("bootstrap_")
            and not col.startswith("proxy_bootstrap_")
        )
    )


RUN_RESULT_COLUMNS = _drop_fixed_or_obsolete_output_columns(RUN_RESULT_COLUMNS)
OPTIM_RESULT_COLUMNS = _drop_fixed_or_obsolete_output_columns(OPTIM_RESULT_COLUMNS)
COMPARISON_COLUMNS = _drop_fixed_or_obsolete_output_columns(COMPARISON_COLUMNS)


def _filter_comparison_row(row: Sequence) -> list:
    return [
        value for col, value in zip(_RAW_COMPARISON_COLUMNS, row)
        if col in COMPARISON_COLUMNS
    ]


class CSVStreamWriter:
    """Helper that appends rows to a CSV file while ensuring headers exist."""

    def __init__(self, path: str, columns: Sequence[str]) -> None:
        self.path = path
        self.columns = tuple(columns)
        os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
        self._delimiter = CSV_DELIMITER
        self._fh = open(path, "w", newline="")
        self._writer = csv.writer(self._fh, delimiter=self._delimiter)
        self._writer.writerow(self.columns)
        self._fh.flush()

    def write_row(self, values: Sequence[object]) -> None:
        if len(values) != len(self.columns):
            raise ValueError(
                f"Expected {len(self.columns)} columns ({self.columns}), got {len(values)} items"
            )
        self._writer.writerow(values)
        self._fh.flush()

    def close(self) -> None:
        try:
            self._fh.close()
        except Exception:
            pass

    def __enter__(self) -> "CSVStreamWriter":
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> Optional[bool]:
        self.close()
        return None


def _row_from_mapping(columns: Sequence[str], data: dict) -> list:
    row = []
    for column in columns:
        value = data.get(column, "")
        if column in {"artifact_time", "artifact_time_bf"} and value in (None, ""):
            value = 0.0
        row.append(value)
    return row


def _remove_artifact_files(prefix: Optional[str]) -> None:
    if not prefix:
        return
    suffixes = (
        "_correlated.csv",
        "_neg_pairs.csv",
        "_candidates.csv",
        "_status.csv",
        "_anomalies.csv",
        "_max_lag_correlated.csv",
    )
    for suffix in suffixes:
        path = f"{prefix}{suffix}"
        if os.path.exists(path):
            try:
                os.remove(path)
            except OSError:
                pass
    base_dir = os.path.dirname(os.path.abspath(prefix))
    base_name = os.path.basename(prefix)
    try:
        for name in os.listdir(base_dir):
            if not name.startswith(base_name + "_"):
                continue
            if ".chunk" not in name:
                continue
            path = os.path.join(base_dir, name)
            try:
                os.remove(path)
            except OSError:
                pass
    except OSError:
        pass

def _run_batch_static(func, batch):
    """Top-level batch helper to avoid bound-method pickling issues."""
    return [func(item) for item in batch]

def _detect_csv_delimiter(path: str, default: str = CSV_DELIMITER) -> str:
    try:
        with open(path, "r", encoding="utf-8", newline="") as handle:
            header = ""
            for line in handle:
                header = line.strip()
                if header:
                    break
            if header:
                has_semicolon = ";" in header
                has_comma = "," in header
                if has_semicolon and not has_comma:
                    return ";"
                if has_comma and not has_semicolon:
                    return ","
            sample = header + handle.read(4096)
    except Exception:
        return default
    if not sample:
        return default
    try:
        dialect = csv.Sniffer().sniff(sample, delimiters=",;")
        if dialect.delimiter:
            return dialect.delimiter
    except Exception:
        pass
    if ";" in sample and sample.count(";") >= sample.count(","):
        return ";"
    return default


def _correlated_codebook_path(csv_path: str) -> str:
    if csv_path.endswith("_correlated.csv"):
        return csv_path[: -len("_correlated.csv")] + "_correlated_codes.csv"
    return f"{csv_path}.codes.csv"


def _write_correlated_codebook(csv_path: str, code_map: dict) -> None:
    code_path = _correlated_codebook_path(csv_path)
    os.makedirs(os.path.dirname(os.path.abspath(code_path)), exist_ok=True)
    with open(code_path, "w", newline="") as file:
        writer = csv.writer(file, delimiter=CSV_DELIMITER)
        writer.writerow(["code", "id"])
        for id_value, code in sorted(code_map.items(), key=lambda item: item[1]):
            writer.writerow([code, id_value])


def _load_correlated_codebook(csv_path: str) -> dict:
    code_path = _correlated_codebook_path(csv_path)
    if not os.path.exists(code_path):
        return {}
    delimiter = _detect_csv_delimiter(code_path, default=CSV_DELIMITER)
    codebook = {}
    try:
        with open(code_path, newline="") as file:
            reader = csv.DictReader(file, delimiter=delimiter)
            for row in reader:
                code = row.get("code")
                id_value = row.get("id")
                if code not in (None, "") and id_value is not None:
                    codebook[str(code)] = id_value
    except OSError:
        return {}
    return codebook


def execute_corrtrack_pass(
    run_kind: str,
    dataset_id: str,
    corrtrack,
    data: np.ndarray,
    ids: Sequence[str],
    metadata: dict,
    corr_val: bool,
    recall_by_window: bool,
    artifact_prefix: Optional[str] = None,
    artifact_mode: str = "iterative",
    artifact_merge_mode: str = "merged",
    verbose: bool = False,
    testing: bool = False,
    monitor: bool = True,
    step_observer=None,
) -> tuple[dict, Optional[tuple], Optional[np.ndarray]]:
    """
    Execute a CorrTrack pass (brute-force or main) and collect runtime statistics.

    Returns:
        record: mapping aligned with RUN_RESULT_COLUMNS.
        runtime_parts: tuple(sketch, candidate, validation, monitor) when applicable.
        corr_flags: correlation indicators for downstream metrics.
    """
    if run_kind not in {"bf", "corrtrack"}:
        raise ValueError(f"Unsupported run_kind '{run_kind}'")

    corr_val = _coerce_to_bool(corr_val, default=True)
    recall_by_window = True
    monitor = _coerce_to_bool(monitor, default=True)
    if not corr_val:
        monitor = False
        if hasattr(corrtrack, "track_min_dist"):
            corrtrack.track_min_dist = False

    record = {key: None for key in RUN_RESULT_COLUMNS}
    record.update(metadata or {})
    record["dataset_id"] = dataset_id
    record["run_kind"] = run_kind
    record["artifact_path"] = artifact_prefix or ""
    record["baseline_mode"] = getattr(corrtrack, "baseline_mode", metadata.get("baseline_mode"))

    n_ts = data.shape[0] - 1
    window_size = corrtrack.window_size
    window_step = corrtrack.window_step
    n_w = int(np.floor((data.shape[1] - window_size) / window_step) + 1)
    total_w = n_ts * n_w

    record["n_ts"] = n_ts
    record["n_w"] = n_w
    record["total_w"] = total_w
    record["mem_w"] = None
    record["window_size"] = window_size
    record["window_step"] = window_step
    record["basic_window"] = corrtrack.basic_window
    record["n_lags"] = corrtrack.n_lags
    record["corr_threshold"] = corrtrack.corr_threshold
    record["grid_max"] = getattr(corrtrack, "grid_max", None)
    record["cell_stretch"] = getattr(corrtrack, "cell_stretch", None)
    record["cell_size"] = getattr(corrtrack, "cell_size", None)
    record["n_vectors"] = getattr(corrtrack, "n_vectors", None)
    record["grid_dimension"] = getattr(corrtrack, "grid_dimension", None)
    record["freq_threshold"] = getattr(corrtrack, "freq_threshold", None)
    record["candidate_backend"] = getattr(
        corrtrack,
        "candidate_backend_effective",
        getattr(corrtrack, "candidate_backend", None),
    )
    # (2026-07-06) Part 1 -- see docs/implementation_log.md.
    record["candidate_lsh_n_bands"] = getattr(corrtrack, "candidate_lsh_n_bands", None)
    for _pk in ("parcorr_k", "parcorr_f", "parcorr_c", "parcorr_neighbor_probe", "parcorr_cell_size", "supports_neg_corr", "supports_lags", "statstream_n_coeffs", "statstream_index_dims", "statstream_apply_dft_filter", "statstream_eps", "statstream_report", "statstream_tolerance", "statstream_bw_coeffs", "corrjoin_ks", "corrjoin_ke", "corrjoin_kb", "corrjoin_eps1", "corrjoin_eps2"):
        record[_pk] = getattr(corrtrack, _pk, None)
    record["candidate_apply_dot_gamma_filter"] = getattr(corrtrack, "candidate_apply_dot_gamma_filter", None)
    record["candidate_hamming_threshold"] = getattr(corrtrack, "candidate_hamming_threshold", None)
    record["candidate_apply_hamming_filter"] = getattr(corrtrack, "candidate_apply_hamming_filter", None)
    record["candidate_hamming_filter_max_frac"] = getattr(corrtrack, "candidate_hamming_filter_max_frac", None)
    record["candidate_lsh_max_candidates_per_query"] = getattr(corrtrack, "candidate_lsh_max_candidates_per_query", None)
    record.update(_candidate_runtime_record_fields(corrtrack))
    record.update(_candidate_search_record_fields(corrtrack))
    record["candidate_parallel_mode"] = getattr(corrtrack, "candidate_parallel_mode", None)
    record["candidate_key_mode"] = getattr(corrtrack, "candidate_key_mode", None)
    record["candidate_key_seed"] = getattr(corrtrack, "candidate_key_seed", None)
    record["candidate_lsh_radius"] = getattr(corrtrack, "candidate_lsh_radius", None)
    record["candidate_ann_m"] = getattr(corrtrack, "candidate_ann_m", None)
    record["candidate_ann_z"] = getattr(corrtrack, "candidate_ann_z", None)
    record["candidate_ann_ef"] = getattr(corrtrack, "candidate_ann_ef", None)
    record["numeric_rows"] = getattr(corrtrack, "numeric_rows", None)
    record.update(_hybrid_validation_record_fields(corrtrack))
    record["exec_mode"] = getattr(corrtrack, "exec", None)
    record["parallel_sketch"] = getattr(corrtrack, "parallel_sketch", None)
    record["parallel_candidates"] = getattr(corrtrack, "parallel_candidates", None)
    record["parallel_validation"] = getattr(corrtrack, "parallel_validation", None)
    record["workers_total"] = getattr(corrtrack, "n_nodes", None)
    record["workers_sketch"] = getattr(corrtrack, "n_sketch_nodes", None)
    record["workers_candidates"] = getattr(corrtrack, "n_candidate_nodes", None)
    if getattr(corrtrack, "parallel_validation", False):
        record["workers_validation"] = getattr(corrtrack, "n_nodes", None)
    else:
        record["workers_validation"] = 1

    artifact_active = bool(artifact_prefix)
    artifact_buffer_max_rows = metadata.get("artifact_buffer_max_rows")
    if artifact_buffer_max_rows in (None, ""):
        artifact_buffer_max_rows = getattr(corrtrack, "_artifact_buffer_max_rows", 250000)
    artifact_policy = _resolve_artifact_save_policy(
        recall_by_window,
        metadata.get("save_only_required_artifacts"),
        metadata.get("save_maxlag_artifacts"),
    )

    artifact_mode_value = (artifact_mode or "iterative").lower()
    if artifact_mode_value not in ("iterative", "final", "buffered"):
        artifact_mode_value = "iterative"
    effective_artifact_mode = artifact_mode_value if artifact_active else "final"
    artifact_merge_mode_value = _resolve_artifact_merge_mode(
        metadata.get("artifact_merge_mode", artifact_merge_mode),
        default="merged",
    )

    corrtrack._configure_artifact_runtime(
        artifact_mode=effective_artifact_mode,
        artifact_buffer_max_rows=artifact_buffer_max_rows,
        artifact_merge_mode=artifact_merge_mode_value,
        recall_by_window=True,
        save_correlated=artifact_policy["save_correlated"],
        save_status=artifact_policy["save_status"],
        save_anomalies=artifact_policy["save_anomalies"],
        save_maxlag=artifact_policy["save_maxlag"],
    )
    corrtrack._step_observer_enabled = bool(step_observer)
    corrtrack._validated_step = {}
    corrtrack._online_window_metrics_only = bool(
        step_observer is not None
        and run_kind == "corrtrack"
        and recall_by_window
        and not corr_val
        and not monitor
        and not artifact_active
    )
    if artifact_active:
        base_dir = os.path.dirname(os.path.abspath(artifact_prefix))
        os.makedirs(base_dir, exist_ok=True)
        corrtrack._start_artifact_logging(artifact_prefix)

    artifact_per_iteration = artifact_active and effective_artifact_mode == "iterative"
    artifact_chunked = artifact_active and effective_artifact_mode in {"iterative", "buffered"}

    artifact_time_total = 0.0
    artifact_time_overlap = 0.0
    artifact_bookkeeping_before = getattr(corrtrack, "artifact_bookkeeping_time", 0.0)

    start_time = time.time()
    # (2026-09-17) per-step wall time of the method call itself (sketch + candidates + validation +
    # monitor for that step, excluding artifact I/O), kept for the online-latency quantiles
    step_times = []
    for start in range(0, data.shape[1] - window_step + 1, window_step):
        chunk = data[:, start : (start + window_step)]
        _ts = time.perf_counter()
        if run_kind == "bf":
            corrtrack.run_bf(chunk, ids, verbose=verbose, testing=testing, corr_val=True, monitor=monitor)
        else:
            corrtrack.run(chunk, ids, verbose=verbose, testing=testing, corr_val=corr_val, monitor=monitor)
        step_times.append(time.perf_counter() - _ts)
        if step_observer is not None:
            _t0 = time.time()
            step_observer(corrtrack)
            elapsed = time.time() - _t0
            artifact_time_total += elapsed
            artifact_time_overlap += elapsed
        if artifact_active and artifact_chunked:
            _t0 = time.time()
            flushed = corrtrack._maybe_flush_artifact_buffers(force=artifact_per_iteration)
            elapsed = time.time() - _t0
            if flushed:
                artifact_time_total += elapsed
                artifact_time_overlap += elapsed
    end_time = time.time()

    if artifact_active and artifact_chunked:
        _t0 = time.time()
        corrtrack._finalize_buffered_artifacts()
        artifact_time_total += time.time() - _t0
    elif artifact_active:
        _t0 = time.time()
        if getattr(corrtrack, "_artifact_save_correlated", True):
            corrtrack._save_correlated(f"{artifact_prefix}_correlated.csv")
        if getattr(corrtrack, "_artifact_save_status", True):
            corrtrack._save_monitor_status(f"{artifact_prefix}_status.csv")
        if getattr(corrtrack, "_artifact_save_anomalies", True):
            corrtrack._save_anomalies(f"{artifact_prefix}_anomalies.csv")
        artifact_time_total += time.time() - _t0

    runtime = end_time - start_time
    runtime_parts = None
    if run_kind == "bf":
        record["sk_time"] = 0.0
        record["cand_time"] = getattr(corrtrack, "candidate_time", 0.0)
        record["val_time"] = getattr(corrtrack, "validation_time", 0.0)
        record["monit_time"] = getattr(corrtrack, "monitor_time", 0.0)
        runtime_parts = (
            0.0,
            record["cand_time"],
            record["val_time"],
            record["monit_time"],
        )
    else:
        runtime = max(runtime, 0.0)
        record["sk_time"] = getattr(corrtrack, "sketch_time", 0.0)
        record["cand_time"] = getattr(corrtrack, "candidate_time", 0.0)
        record["val_time"] = getattr(corrtrack, "validation_time", 0.0)
        record["monit_time"] = getattr(corrtrack, "monitor_time", 0.0)
        runtime_parts = (
            record["sk_time"],
            record["cand_time"],
            record["val_time"],
            record["monit_time"],
        )

    runtime = max(runtime - artifact_time_overlap, 0.0)
    # online-latency profile: quantiles of the per-step time (seconds), the steady-state part only
    # (steps after the first full window, when every arm has a populated index/history)
    _st = np.asarray(step_times, dtype=np.float64)
    _warm = int(math.ceil(window_size / window_step)) if isinstance(window_size, (int, np.integer)) else 1
    _ss = _st[_warm:] if _st.shape[0] > _warm + 4 else _st
    # boxplot ticks (user, 2026-09-18): min, Q1, median, Q3, max, the Tukey whisker ends
    # (last observations inside Q1 - 1.5 IQR and Q3 + 1.5 IQR), the outlier count, and the mean
    record["n_steps"] = int(_st.shape[0])
    if _ss.size:
        _q1, _q2, _q3 = (float(v) for v in np.quantile(_ss, (0.25, 0.5, 0.75)))
        _iqr = _q3 - _q1
        _lo_in = _ss[_ss >= _q1 - 1.5 * _iqr]; _hi_in = _ss[_ss <= _q3 + 1.5 * _iqr]
        record.update(step_time_min=float(_ss.min()), step_time_q1=_q1, step_time_median=_q2, step_time_q3=_q3, step_time_max=float(_ss.max()),
                      step_time_whisker_lo=float(_lo_in.min()) if _lo_in.size else _q1, step_time_whisker_hi=float(_hi_in.max()) if _hi_in.size else _q3,
                      step_time_outliers=int(((_ss < _q1 - 1.5 * _iqr) | (_ss > _q3 + 1.5 * _iqr)).sum()), step_time_mean=float(_ss.mean()))
    else:
        record.update({k: None for k in ("step_time_min", "step_time_q1", "step_time_median", "step_time_q3", "step_time_max",
                                         "step_time_whisker_lo", "step_time_whisker_hi", "step_time_outliers", "step_time_mean")})

    if artifact_active and getattr(corrtrack, "_artifact_save_maxlag", True):
        _t0 = time.time()
        corrtrack._save_max_lag_correlated(f"{artifact_prefix}_max_lag_correlated.csv")
        artifact_time_total += time.time() - _t0

    artifact_bookkeeping_delta = max(
        getattr(corrtrack, "artifact_bookkeeping_time", 0.0) - artifact_bookkeeping_before,
        0.0,
    )
    artifact_time_total += artifact_bookkeeping_delta
    artifact_time_overlap += artifact_bookkeeping_delta
    runtime = max(runtime - artifact_bookkeeping_delta, 0.0)

    record["runtime"] = runtime
    record["artifact_time"] = artifact_time_total
    if hasattr(corrtrack, "n_lagged_windows"):
        record["mem_w"] = corrtrack.n_lagged_windows - 1
    record["correlated"] = getattr(corrtrack, "validated_candidates", 0)
    record["tested"] = getattr(corrtrack, "tested_candidates", 0)
    record["total_candidates"] = getattr(corrtrack, "total_candidates", 0)
    # (2026-09-18) precision BEFORE validation: the fraction of generated candidates that are true
    # correlations (StatStream's Fig. 5 "precision", CorrJoin's 1/r1 complement); for an all-pairs
    # arm this is the dataset's correlation density at the threshold
    _tc = record["total_candidates"] or 0
    record["candidate_precision"] = (float(record["correlated"]) / float(_tc)) if _tc else None
    record.update(_candidate_search_record_fields(corrtrack))
    pair_min_dist = getattr(corrtrack, "pair_min_dist", None)
    record["pair_min_dist"] = str(pair_min_dist) if pair_min_dist is not None else ""
    record.update(_hybrid_validation_record_fields(corrtrack))

    corrtrack._step_observer_enabled = False
    corrtrack._online_window_metrics_only = False
    corrtrack._validated_step = {}

    if artifact_chunked:
        corr_flags = None
    elif recall_by_window:
        # (2026-09-10) Prefer the numeric (rows, corrs) form -- compute_metrics_bf takes it
        # directly and skips the per-key Python normalization. Falls back to the string dict
        # for a tracker without the accumulator (e.g. CorrTrackMultiWindow).
        if hasattr(corrtrack, "correlated_rows") and callable(corrtrack.correlated_rows):
            corr_flags = NumericCorrelatedFlags(*corrtrack.correlated_rows())
        else:
            corr_flags = getattr(corrtrack, "correlated", None)
    else:
        corr_flags = corrtrack.get_correlation_flags(data.shape[1], 0)

    return record, runtime_parts, corr_flags


_BASELINE_SUPPORTS_NEG_CORR = {
    "bruteforce": "native",
    "bf_incremental": "native",
    "filcorr": "enabled_by_us",
    "braid": "specified",
    "tsubasa": "native",
}

# (2026-09-23) the same disclosure vocabulary for the lag capability: "native" = the paper searches lags
# and evaluates it, "enabled_by_us" = the extension is ours (TSUBASA, whose Lemma 1 holds between segments
# shifted by whole basic windows; see Candidates_BF_TSUBASA). The arm sets it itself when it depends on the
# configuration, and this table is the fallback for the ones that do not.
_BASELINE_SUPPORTS_LAGS = {
    "bruteforce": "native",
    "bf_incremental": "native",
    "filcorr": "native",          # lagged correlation IS FilCorr's problem statement
    "braid": "native",            # lag search is BRAID's whole contribution
    "tsubasa": "native",          # synchronous runs only; a lagged run is tagged enabled_by_us below
}


def run_and_log_bruteforce(
    dataset_id: str,
    data: np.ndarray,
    ids: Sequence[str],
    base_config: dict,
    output_csv: str,
    metadata: Optional[dict] = None,
    recall_by_window: bool = True,
    verbose: Optional[bool] = None,
    testing: Optional[bool] = None,
    artifact_prefix: Optional[str] = None,
) -> tuple[dict, tuple, Optional[np.ndarray]]:
    metadata = dict(metadata or {})
    baseline_mode = _resolve_baseline_mode(base_config.get("baseline_mode", "bruteforce"))
    metadata.setdefault("mode", "bf")
    metadata.setdefault("alg", metadata.get("alg", "bf"))
    metadata.setdefault("optim", metadata.get("optim", "baseline"))
    if baseline_mode != "bruteforce" and metadata.get("optim") in {"baseline", "bf_baseline"}:
        metadata["optim"] = f"{baseline_mode}_baseline"
    metadata.setdefault("baseline_mode", baseline_mode)
    metadata.setdefault("artifact_buffer_max_rows", base_config.get("artifact_buffer_max_rows"))
    metadata.setdefault("artifact_merge_mode", base_config.get("artifact_merge_mode"))
    metadata.setdefault(
        "save_only_required_artifacts",
        base_config.get("save_only_required_artifacts"),
    )
    metadata.setdefault("save_maxlag_artifacts", base_config.get("save_maxlag_artifacts"))

    artifact_mode = base_config.get("artifact_mode", "iterative")
    artifact_merge_mode = base_config.get("artifact_merge_mode", "merged")
    monitor = _coerce_to_bool(base_config.get("monitor", True), default=True)

    corrtrack = CorrTrack(
        window_size=base_config["window_size"],
        basic_window=base_config.get("basic_window"),
        window_step=base_config["window_step"],
        n_vectors=1,
        n_lags=base_config["n_lags"],
        seed=None,
        seed_toggle=None,
        corr_threshold=base_config["corr_threshold"],
        neg_corr=base_config.get("neg_corr", False),
        # (2026-08-24) Was hardcoded False regardless of base_config --
        # brute force's ground truth is validated through this same
        # CorrTrack instance (_get_validated_corr_numeric reading
        # _get_validation_window_data()), so leaving this hardcoded meant
        # brute force could never be made consistent with a preprocess=True
        # online run (fixed or hyperopt-selected) no matter what the caller
        # asked for. See docs/implementation_log.md.
        preprocess=_coerce_to_bool(base_config.get("preprocess", False), default=False),
        exec=base_config.get("exec", "thread"),
        max_workers=base_config.get("max_workers", 0),
        parallel_sketch=base_config.get("parallel_sketch"),
        parallel_candidates=base_config.get("parallel_candidates"),
        parallel_validation=base_config.get("parallel_validation"),
        track_min_dist=base_config.get("track_min_dist", True),
        validation_metric=base_config.get("validation_metric", "pearson"),
    )
    corrtrack.baseline_mode = baseline_mode
    # (2026-09-17) Evidence tier of the arm's negative-correlation handling, written to the
    # record (comparison plan section 5b.5). Pattern-A arms are all-pairs, so the tag is per
    # method: FilCorr's Eq. 7 takes the max of *signed* correlations and our port adds abs();
    # BRAID's Definition 1 uses |R(l)| but never ran a negative-correlation experiment;
    # TSUBASA's Alg. 2 tests |c| > theta in every experiment.
    corrtrack.supports_neg_corr = _BASELINE_SUPPORTS_NEG_CORR.get(baseline_mode, "native")
    # the Pattern A arm's own capability, not the host CorrTrack's: TSUBASA is synchronous as published,
    # so a lagged run of it is our extension (Candidates_BF_TSUBASA's lagged note)
    _lag_tier = _BASELINE_SUPPORTS_LAGS.get(baseline_mode, "native")
    if baseline_mode == "tsubasa" and int(base_config.get("n_lags") or 0) > 0:
        _lag_tier = "enabled_by_us"
    corrtrack.supports_lags = _lag_tier
    if baseline_mode == "filcorr":
        corrtrack.filcorr_fs = _to_float_safe(base_config.get("filcorr_fs", 0.0)) or 0.0
        corrtrack.filcorr_ft = _to_float_safe(base_config.get("filcorr_ft", 0.5)) or 0.5
        corrtrack.filcorr_sampling_rate = (
            _to_float_safe(base_config.get("filcorr_sampling_rate", 1.0)) or 1.0
        )
        metadata.setdefault("filcorr_fs", corrtrack.filcorr_fs)
        metadata.setdefault("filcorr_ft", corrtrack.filcorr_ft)
        metadata.setdefault("filcorr_sampling_rate", corrtrack.filcorr_sampling_rate)
    if baseline_mode == "braid":
        corrtrack.braid_b = int(_to_float_safe(base_config.get("braid_b", 16)) or 16)
        corrtrack.braid_gamma = _to_float_safe(base_config.get("braid_gamma", 0.4))
        if corrtrack.braid_gamma is None:
            corrtrack.braid_gamma = 0.4
        corrtrack.braid_thin = _coerce_to_bool(base_config.get("braid_thin", False), default=False)
        corrtrack.braid_thin_d0 = int(_to_float_safe(base_config.get("braid_thin_d0", 400)) or 400)
        corrtrack.braid_report_mode = str(base_config.get("braid_report_mode", "all_lags") or "all_lags")
        for k in ("braid_b", "braid_gamma", "braid_thin", "braid_thin_d0", "braid_report_mode"):
            metadata.setdefault(k, getattr(corrtrack, k))

    if verbose is None:
        verbose = _coerce_to_bool(base_config.get("verbose", False))
    if testing is None:
        testing = _coerce_to_bool(base_config.get("testing", False))

    record, runtime_parts, corr_flags = execute_corrtrack_pass(
        "bf",
        dataset_id,
        corrtrack,
        data,
        ids,
        metadata,
        corr_val=True,
        recall_by_window=True,
        artifact_prefix=artifact_prefix,
        artifact_mode=artifact_mode,
        artifact_merge_mode=artifact_merge_mode,
        verbose=bool(verbose),
        testing=bool(testing),
        monitor=bool(monitor),
    )
    record["preprocess"] = corrtrack.preprocess
    record["seed"] = None
    record["seed_toggle"] = None
    record["sketch_norm"] = getattr(corrtrack, "sketch_norm", None)
    record["nodes"] = metadata.get("nodes", base_config.get("max_workers"))
    record["freq_threshold"] = getattr(corrtrack, "freq_threshold", None)

    with CSVStreamWriter(output_csv, RUN_RESULT_COLUMNS) as writer:
        writer.write_row(_row_from_mapping(RUN_RESULT_COLUMNS, record))
    return record, runtime_parts, corr_flags


def run_and_log_corrtrack(
    dataset_id: str,
    data: np.ndarray,
    ids: Sequence[str],
    base_config: dict,
    run_params: dict,
    output_csv: str,
    metadata: Optional[dict] = None,
    recall_by_window: bool = True,
    corr_val: bool = True,
    monitor: bool = True,
    verbose: Optional[bool] = None,
    testing: Optional[bool] = None,
    artifact_prefix: Optional[str] = None,
) -> tuple[dict, tuple, Optional[np.ndarray]]:
    metadata = dict(metadata or {})
    metadata.setdefault("mode", "main")
    metadata.setdefault("alg", metadata.get("alg"))
    metadata.setdefault("optim", metadata.get("optim", "main"))
    metadata.setdefault("artifact_buffer_max_rows", run_params.get("artifact_buffer_max_rows") or base_config.get("artifact_buffer_max_rows"))
    metadata.setdefault(
        "artifact_merge_mode",
        run_params.get("artifact_merge_mode", base_config.get("artifact_merge_mode")),
    )
    metadata.setdefault(
        "save_only_required_artifacts",
        run_params.get("save_only_required_artifacts", base_config.get("save_only_required_artifacts")),
    )
    metadata.setdefault(
        "save_maxlag_artifacts",
        run_params.get("save_maxlag_artifacts", base_config.get("save_maxlag_artifacts")),
    )

    def _to_int(value):
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    def _to_float(value):
        try:
            return float(value)
        except (TypeError, ValueError):
            return None

    artifact_mode = (
        run_params.get("artifact_mode")
        or base_config.get("artifact_mode")
        or "iterative"
    )
    artifact_merge_mode = (
        run_params.get("artifact_merge_mode")
        or base_config.get("artifact_merge_mode")
        or "merged"
    )

    n_vectors = _to_int(run_params.get("n_vectors"))
    grid_dimension = _to_int(run_params.get("grid_dimension"))
    cell_stretch = _resolve_cell_stretch(
        run_params.get("cell_stretch"),
        run_params.get("cell_size"),
        base_config["corr_threshold"],
        n_vectors,
        grid_dimension,
        full_vector_candidates=True,
    )
    if cell_stretch is None or cell_stretch <= 0.0:
        cell_stretch = 1.0

    feature_kwargs = _extract_feature_overrides({**base_config, **run_params})
    run_seed = _to_int(run_params.get("seed"))
    seed_toggle = _to_int(run_params.get("seed_toggle"))

    corrtrack_common_kwargs = dict(
        n_vectors=n_vectors,
        n_lags=base_config["n_lags"],
        seed=run_seed,
        seed_toggle=seed_toggle,
        freq_threshold=_to_float(run_params.get("freq_threshold")),
        corr_threshold=base_config["corr_threshold"],
        neg_corr=base_config.get("neg_corr", False),
        preprocess=run_params.get("preprocess"),
        exec=base_config.get("exec", "thread"),
        max_workers=base_config.get("max_workers", 0),
        parallel_sketch=base_config.get("parallel_sketch"),
        parallel_candidates=base_config.get("parallel_candidates"),
        parallel_validation=base_config.get("parallel_validation"),
        track_min_dist=base_config.get("track_min_dist", True),
        **feature_kwargs,
    )
    window_size_cfg = base_config["window_size"]
    window_sizes_list = (
        [int(v) for v in window_size_cfg]
        if isinstance(window_size_cfg, (list, tuple))
        else [int(window_size_cfg)]
    )
    if len(window_sizes_list) >= 2:
        # (2026-07-30) WINDOW_SIZE itself now selects single- vs multi-window
        # execution (WINDOW_SIZES dropped as a separate parameter): a scalar
        # or single-element list runs plain CorrTrack (unchanged below);
        # >=2 distinct sizes runs CorrTrackMultiWindow, which shares one
        # incremental sketch stream across all requested sizes. Verified
        # (see docs/implementation_log.md's 2026-07-30 entry) that
        # execute_corrtrack_pass drives CorrTrackMultiWindow transparently --
        # its .run()/.run_bf() signatures match CorrTrack's exactly, and
        # __getattr__ forwards every other attribute lookup to the
        # underlying max-window CorrTrack tracker.
        corrtrack = CorrTrackMultiWindow(
            window_sizes=window_sizes_list,
            basic_window=base_config.get("basic_window"),
            window_step=base_config["window_step"],
            **corrtrack_common_kwargs,
        )
    else:
        corrtrack = CorrTrack(
            window_size=window_sizes_list[0],
            basic_window=base_config.get("basic_window"),
            window_step=base_config["window_step"],
            **corrtrack_common_kwargs,
        )

    if verbose is None:
        verbose = _coerce_to_bool(base_config.get("verbose", False))
    if testing is None:
        testing = _coerce_to_bool(base_config.get("testing", False))

    record, runtime_parts, corr_flags = execute_corrtrack_pass(
        "corrtrack",
        dataset_id,
        corrtrack,
        data,
        ids,
        metadata,
        corr_val=corr_val,
        recall_by_window=True,
        artifact_prefix=artifact_prefix,
        artifact_mode=artifact_mode,
        artifact_merge_mode=artifact_merge_mode,
        verbose=bool(verbose),
        testing=bool(testing),
        monitor=bool(monitor),
    )

    record["preprocess"] = run_params.get("preprocess")
    record["seed"] = run_seed
    record["seed_toggle"] = seed_toggle
    record["sketch_norm"] = corrtrack.sketch_norm
    record["candidate_backend"] = getattr(
        corrtrack,
        "candidate_backend_effective",
        getattr(corrtrack, "candidate_backend", None),
    )
    # (2026-07-06) Part 1 -- see docs/implementation_log.md.
    record["candidate_lsh_n_bands"] = getattr(corrtrack, "candidate_lsh_n_bands", None)
    for _pk in ("parcorr_k", "parcorr_f", "parcorr_c", "parcorr_neighbor_probe", "parcorr_cell_size", "supports_neg_corr", "supports_lags", "statstream_n_coeffs", "statstream_index_dims", "statstream_apply_dft_filter", "statstream_eps", "statstream_report", "statstream_tolerance", "statstream_bw_coeffs", "corrjoin_ks", "corrjoin_ke", "corrjoin_kb", "corrjoin_eps1", "corrjoin_eps2"):
        record[_pk] = getattr(corrtrack, _pk, None)
    record["candidate_apply_dot_gamma_filter"] = getattr(corrtrack, "candidate_apply_dot_gamma_filter", None)
    record["candidate_hamming_threshold"] = getattr(corrtrack, "candidate_hamming_threshold", None)
    record["candidate_apply_hamming_filter"] = getattr(corrtrack, "candidate_apply_hamming_filter", None)
    record["candidate_hamming_filter_max_frac"] = getattr(corrtrack, "candidate_hamming_filter_max_frac", None)
    record["candidate_lsh_max_candidates_per_query"] = getattr(corrtrack, "candidate_lsh_max_candidates_per_query", None)
    record.update(_candidate_runtime_record_fields(corrtrack))
    record.update(_candidate_search_record_fields(corrtrack))
    record["candidate_parallel_mode"] = getattr(corrtrack, "candidate_parallel_mode", None)
    record["candidate_key_mode"] = getattr(corrtrack, "candidate_key_mode", None)
    record["candidate_key_seed"] = getattr(corrtrack, "candidate_key_seed", None)
    record["candidate_lsh_radius"] = getattr(corrtrack, "candidate_lsh_radius", None)
    record["candidate_ann_m"] = getattr(corrtrack, "candidate_ann_m", None)
    record["candidate_ann_z"] = getattr(corrtrack, "candidate_ann_z", None)
    record["candidate_ann_ef"] = getattr(corrtrack, "candidate_ann_ef", None)
    record["numeric_rows"] = getattr(corrtrack, "numeric_rows", None)
    record["freq_threshold"] = _to_float(run_params.get("freq_threshold"))
    record["n_vectors"] = n_vectors
    record["grid_dimension"] = grid_dimension
    record["cell_stretch"] = cell_stretch
    record["nodes"] = metadata.get("nodes", base_config.get("max_workers"))

    with CSVStreamWriter(output_csv, RUN_RESULT_COLUMNS) as writer:
        writer.write_row(_row_from_mapping(RUN_RESULT_COLUMNS, record))

    return record, runtime_parts, corr_flags


def _coerce_to_bool(value, default=False):
    if value is None:
        return default
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "t", "yes", "y"}
    return bool(value)


def _resolve_artifact_save_policy(
    recall_by_window,
    save_only_required_artifacts=False,
    save_maxlag_artifacts=True,
):
    save_only_required = _coerce_to_bool(save_only_required_artifacts, default=False)
    save_maxlag = _coerce_to_bool(save_maxlag_artifacts, default=True)

    if save_only_required:
        return {
            "save_correlated": bool(recall_by_window),
            "save_status": False,
            "save_anomalies": not bool(recall_by_window),
            "save_maxlag": save_maxlag,
        }

    return {
        "save_correlated": True,
        "save_status": True,
        "save_anomalies": True,
        "save_maxlag": save_maxlag,
    }


def _resolve_artifact_merge_mode(value, default="merged"):
    if value is None or value == "":
        value = default
    if isinstance(value, str):
        key = value.strip().lower().replace("-", "_")
    else:
        key = str(value).strip().lower().replace("-", "_")
    aliases = {
        "merge": "merged",
        "merged": "merged",
        "final": "merged",
        "chunks": "chunks",
        "chunk": "chunks",
        "chunked": "chunks",
        "unmerged": "chunks",
        "skip": "chunks",
        "none": "chunks",
    }
    return aliases.get(key, aliases.get(str(default).strip().lower(), "merged"))


def _resolve_parallel_flag(value, default=False) -> bool:
    return _coerce_to_bool(value, default=bool(default))


def _resolve_candidate_backend(value, default="auto"):
    if value is None:
        value = default
    if isinstance(value, str):
        key = value.strip().lower()
    else:
        key = str(value).strip().lower()
    aliases = {
        "tree": "bptree",
        "bst": "bptree",
        "balanced": "bptree",
        "bucket": "sorted_arrays_bs",
        "bucketed": "sorted_arrays_bs",
        "bucketed_bptree": "sorted_arrays_bs",
        "bucketed_tree": "sorted_arrays_bs",
        "hash_buckets": "sorted_arrays_bs",
        "hash-buckets": "sorted_arrays_bs",
        "bucketed_multi": "sorted_arrays_bs",
        "sorted_bs": "sorted_arrays_bs",
        "sorted_array_bs": "sorted_arrays_bs",
        # (2026-07-05) renamed from "bucketed_bst" -- the backend never used a
        # BST (binary search tree); it's flat sorted arrays per key dimension
        # plus binary search (bisect). Kept as a backward-compat alias so
        # existing configs/artifacts referencing the old name keep working.
        # See docs/implementation_log.md.
        "bucketed_bst": "sorted_arrays_bs",
        # (2026-07-06) InstinctIndex -- experimental approximate graph
        # backend. See docs/implementation_log.md, "InstinctIndex:
        # experimental approximate graph backend".
        "graph": "instinct",
        "instinct_index": "instinct",
        # (2026-07-09) SignLSHBandIndex -- LSH sign-bit banding pre-filter.
        # See docs/implementation_log.md, "SignLSHBandIndex: lsh_sign_dot
        # backend" and the preceding "sign_alignment_frac / LSH sign-bit
        # banding" diagnostic entry. Replaces the removed "topk_inverted"
        # backend (see docs/implementation_log.md's 2026-07-08 correction --
        # its top-m dominant-coordinate approach degenerated to a near-full
        # scan on real data; this is a structurally different mechanism).
        "lsh": "lsh_sign_dot",
        "sign_lsh": "lsh_sign_dot",
        "lsh_band": "lsh_sign_dot",
        "band": "lsh_sign_dot",
        # (2026-07-10) HammingExactIndex: exact packed-bit Hamming
        # pre-filter (no bands/buckets at all) -- see
        # docs/implementation_log.md, "outside-the-box backends" entry.
        "hamming_exact": "lsh_hamming_exact",
        "packed_hamming": "lsh_hamming_exact",
        # (2026-07-15) CircularGroupedExactIndex: full-scan pre-filter using
        # circular-sector group matching (AND within a group of random 2D
        # projection planes, OR across groups) -- see
        # docs/implementation_log.md, 2026-07-15 circular-band-LSH entries.
        "circular_lsh": "circular_grouped_lsh",
        "circular_grouped": "circular_grouped_lsh",
        "grouped_circular_lsh": "circular_grouped_lsh",
        "circular_band_lsh": "circular_grouped_lsh",
        # (2026-07-15) MultiDimThetaIndex: the supervisors' idea 1 (a
        # decoupled, independently-swept theta) combined with idea 2 (one
        # independent tree/index per sketch dimension, intersected) -- see
        # docs/implementation_log.md, 2026-07-15 "bptree MIXED supervisor
        # ideas" entries, and diag_bptree_mixed_ideas.py.
        "bptree_mixed": "bptree_mixed",
        "multi_dim_theta": "bptree_mixed",
        "mixed_bptree": "bptree_mixed",
        "theta_bptree": "bptree_mixed",
    }
    key = aliases.get(key, key)
    if key in {"hamming", "hamming_multi", "hamming-multi", "hamming_mi", "hamming_multiindex", "simhash", "sign_code", "sign-code"}:
        raise ValueError("candidate_backend='hamming_multiindex' has been removed")
    if key in {"pivot", "pivots", "pivot_sorted", "pivot-sorted", "pivot_sorted_array", "pivot-sorted-array", "pivot_array", "pivot-array"}:
        raise ValueError("candidate_backend='pivot_sorted_array' has been removed")
    if key in {"blocked_lazy", "blocked", "lazy_blocked", "blocked-lazy", "blocked_sorted", "blocked-sorted"}:
        raise ValueError("candidate_backend='blocked_lazy' has been removed")
    if key in {"vptree", "vp", "vp_tree", "vp-tree"}:
        raise ValueError("candidate_backend='vptree' has been removed")
    if key in {"angular_lsh", "angular", "angular-lsh", "multi_projection", "multi-projection", "projection_lsh", "projection-lsh"}:
        raise ValueError("candidate_backend='angular_lsh' has been removed")
    if key in {"dynamic_graph_ann", "graph_ann", "dynamic-graph-ann", "nsw"}:
        raise ValueError("candidate_backend='dynamic_graph_ann' has been removed")
    # (2026-07-13) ivf_hamming (IVFHammingIndex) and lsh_ternary_exact
    # (TernaryExactIndex) removed per explicit instruction -- neither beat
    # lsh_hamming_exact on both speed and recall (see
    # docs/implementation_log.md's 2026-07-10 "multi-probe" and
    # "ternary-scoring variant" entries for the full evidence).
    if key in {"ivf_hamming", "ivf", "ivf_hamming_exact", "ivf-hamming"}:
        raise ValueError("candidate_backend='ivf_hamming' has been removed")
    if key in {"lsh_ternary_exact", "ternary_exact", "packed_ternary", "ternary"}:
        raise ValueError("candidate_backend='lsh_ternary_exact' has been removed")
    # (2026-07-27) Release restructuring per explicit instruction: every
    # candidate_backend other than lsh_sign_dot/lsh_hamming_exact (and the
    # unconditional flat brute-force reference, kept as the baseline every
    # speedup claim in this project is measured against) removed from
    # corrtrack_release_dev. See docs/implementation_log.md's 2026-07-27
    # release-restructuring entries; corrtrack_release_backup2 preserves
    # the pre-cleanup tree with all backends intact.
    if key in {"bptree", "bptree_mixed"}:
        raise ValueError(f"candidate_backend='{key}' has been removed")
    if key in {"sorted_arrays_bs"}:
        raise ValueError("candidate_backend='sorted_arrays_bs' has been removed")
    if key in {"instinct"}:
        raise ValueError("candidate_backend='instinct' has been removed")
    if key in {"circular_grouped_lsh"}:
        raise ValueError("candidate_backend='circular_grouped_lsh' has been removed")
    if key in {"lsh_grid_dot"}:
        raise ValueError("candidate_backend='lsh_grid_dot' has been removed")
    # (2026-07-31) GlobalOrdinalTransformer/global_ordinal_comparisons
    # removed: incremental_concordance_multichannel (a per-gap union tier-1
    # over ConcordanceSketchState) was found, via direct real-data
    # benchmarking, to strictly dominate global_ordinal_comparisons'
    # recall at every window_size tested (256/1024/2048/4096: 97.7%/100%/
    # 100%/100% vs. 83.0%/99.1%/98.2%/93.2%), precision 100% throughout --
    # see docs/implementation_log.md's 2026-07-31 entry. GlobalOrdinal
    # Transformer's own recompute-from-scratch-every-step design (unlike
    # concordance's incremental one) no longer has a real-world edge to
    # justify keeping it.
    if key in {"global_ordinal", "ordinal", "ordinal_comparisons", "global_ordinal_comparisons"}:
        raise ValueError("candidate_backend='global_ordinal_comparisons' has been removed")
    # (2026-07-31, later) Single-vector ConcordanceSketchState removed:
    # once ConcordanceMultiGapIndex's own missing Hamming-filter wiring was
    # fixed (see docs/implementation_log.md's 2026-07-31(g) entry),
    # touched_candidates became EXACTLY equal between the two
    # representations at every window_size where multiscale_gaps floors to
    # one gap (>=1024), removing single-vector concordance's last real
    # advantage -- multichannel now strictly dominates or ties it
    # everywhere (97.7% vs 54.8% recall at window_size=256, identical
    # touched_candidates at window_size>=1024). Aliases fail loudly rather
    # than silently redirecting to the multichannel backend, matching the
    # established pattern for every other removed backend this session.
    if key in {"incremental_concordance", "concordance", "concordance_sketch", "incremental_ordinal"}:
        raise ValueError("candidate_backend='incremental_concordance' has been removed")
    # (2026-07-31) Per-gap union tier-1 for concordance -- direct response
    # to a real, measured recall gap at small window_size (n_gaps>1, before
    # multiscale_gaps' own n_gaps=1 floor kicks in at window_size>=1024):
    # concatenating all gaps into one globally-normalized vector dilutes
    # whichever single gap actually carries the real signal for a pair
    # near corr_threshold (verified directly: combined-vector cosine mean
    # only 0.152, 35.7% actually NEGATIVE, at window_size=256). Mirrors
    # distance_corr_sketch_multichannel's own diagnosis and fix exactly --
    # see ConcordanceMultiGapIndex's docstring (concordance_sketch.py) and
    # docs/implementation_log.md's 2026-07-31 entry.
    concordance_multichannel_aliases = {
        "incremental_concordance_multichannel", "concordance_multichannel",
        "concordance_multi_gap", "concordance_multigap",
    }
    if key in concordance_multichannel_aliases:
        return "incremental_concordance_multichannel"
    # (2026-07-31, Phase 4) Single-vector distance_corr_sketch removed:
    # confirmed via Phase 0b (docs/implementation_log.md's 2026-07-30(m)/(n)
    # and 2026-07-31 entries) that distance_corr_sketch_multichannel
    # strictly dominates it on recall at every K tested (perfect recall at
    # K>=16, vs. noisy 75-90% for the single-vector representation), with
    # no offsetting tradeoff (unlike single-vector concordance's own real
    # large-window speed advantage, which is why THAT one was kept). No
    # representation-axis name ever pointed here either (see
    # _REPRESENTATION_ALIASES' own "sketch_proj now means Pearson" comment).
    if key in {"distance_corr_sketch", "dcor_sketch", "distance_correlation_sketch", "dist_corr_sketch"}:
        raise ValueError("candidate_backend='distance_corr_sketch' has been removed")
    # (2026-07-31, Phase 4) "Skip tier-1" variant removed too: it existed
    # specifically to preserve single-vector distance_corr_sketch's own
    # tier-2 gate under unconditional enumeration -- with that
    # representation gone, there is nothing left for this name to be an
    # alternative TO. (representation=sketch_multichannel + backend=
    # brute_force still works via the new axis, just as the plain, generic
    # "brute_force" backend -- representation is a deliberate no-op there,
    # see _resolve_representation_backend's own comment -- not as a
    # distinct gate-preserving combination the way this name used to be.)
    if key in {"distance_corr_sketch_exhaustive", "dcor_sketch_exhaustive", "distance_corr_sketch_brute_force", "dcor_sketch_brute_force"}:
        raise ValueError("candidate_backend='distance_corr_sketch_exhaustive' has been removed")
    # (2026-07-30) Multi-channel union tier-1 -- direct response to "I am
    # still interested in making tier 1 work better... I want smart
    # filtering with no all pair enumeration" after confirming
    # distance_corr_sketch's own tier-1 (single concatenated vector, one
    # global cosine) parameter space was exhausted (docs/implementation_
    # log.md's 2026-07-30(l) entry). Verified directly (2026-07-30(m)):
    # the best SINGLE-channel (same frequency, diagonal) cosine alignment
    # between genuinely dependent series is dramatically stronger and
    # cleanly separated from independent pairs than the concatenated
    # vector's own diluted signal. DistanceCorrSketchMultiChannelIndex
    # (distance_corr_sketch.py) maintains 2K SEPARATE SignLSHBandIndex
    # instances (one per channel) and proposes a candidate if ANY single
    # channel's index retrieves it (union across channels) -- see
    # docs/implementation_log.md's 2026-07-30(n) entry for the real-data
    # recall/precision/touched_frac results.
    distance_corr_sketch_multichannel_aliases = {
        "distance_corr_sketch_multichannel", "dcor_sketch_multichannel",
        "distance_corr_sketch_multi_channel", "dcor_sketch_multi_channel",
    }
    if key in distance_corr_sketch_multichannel_aliases:
        return "distance_corr_sketch_multichannel"
    # (2026-07-30) Genuine, unconditional brute-force reference -- added
    # after finding "flat" is NOT a valid ground-truth/wall-time baseline
    # for non-Pearson validation_metric values. "flat" always builds and
    # gates through the project's default Pearson-style sketch for
    # candidate GENERATION regardless of validation_metric (confirmed
    # directly: its own recall against a truly exhaustive enumeration was
    # only 83.6% at one real config, and even its "loose threshold" ground-
    # truth convention was found NOT to fully saturate at every cell_size
    # tried) -- a real, disclosed methodology gap for spearman/kendall/
    # dist_corr, see docs/implementation_log.md's 2026-07-30(i) entry.
    # "brute_force" enumerates every (recent x alive) pair directly from
    # the Candidates-level window registry (_win_sid_idx/_win_time/_win_w),
    # with NO representation, index, or gate of any kind -- correct by
    # construction for any validation_metric, not just Pearson.
    brute_force_aliases = {"brute_force", "true_brute_force", "exhaustive", "unconditional"}
    if key in brute_force_aliases:
        return "brute_force"
    # (2026-07-31, Phase 4) "flat" removed -- superseded by "brute_force"
    # (this session's own finding: "flat" is NOT a valid ground-truth/
    # wall-time baseline for non-Pearson validation_metric, since it always
    # gates candidate GENERATION through the default Pearson-style sketch
    # regardless of validation_metric; see docs/implementation_log.md's
    # 2026-07-30(i) entry). Following the 2026-07-27(e) precedent: the
    # user-facing removal is here (raise, don't silently fall through);
    # the internal Candidates-level "flat" branches (_increment_candidates
    # et al.) are left in place as harmless, now-unreachable dead code --
    # the same judgment call already made for bptree/instinct/sorted_
    # arrays_bs's own dispatch conditionals scattered through that same
    # method, where hand-editing every site in a 10,000+-line file was
    # judged riskier than the cost of a little dead code.
    if key in {"flat"}:
        raise ValueError("candidate_backend='flat' has been removed")
    if key in ("parcorr_grid", "statstream_grid", "corrjoin_double_filter", "all_pairs"):
        return key                      # (2026-09-17) competitor arms -- see ParCorrGridIndex / StatStreamGridIndex / CorrJoinDoubleFilterIndex; all_pairs = ablation (AllPairsGateIndex)
    if key not in {"brute_force", "auto", "lsh_sign_dot", "lsh_hamming_exact"}:
        key = default
    return key


# Candidate search is controlled by two orthogonal parameters:
#
#   data_representation -- which vector representation to build from the
#     raw window data before searching for candidates.
#       "auto"               pick per validation_metric (see below).
#       "raw"                no representation at all: enumerate every
#                             (recent x alive) pair directly. Only valid
#                             with candidate_backend="auto"/"brute_force".
#       "sketch_proj"        Pearson single-vector projection sketch.
#       "sketch_concordance" per-gap union sketch (spearman/kendall).
#       "sketch_multichannel" per-channel union sketch (dist_corr).
#     "auto" resolves by validation_metric: pearson -> sketch_proj,
#     spearman/kendall -> sketch_concordance, dist_corr -> sketch_multichannel.
#
#   candidate_backend -- which search/index mechanism retrieves candidates
#     from that representation.
#       "auto"          resolves to "lsh_approx" (the established default).
#       "lsh_approx"    SignLSHBandIndex (approximate sign-bit banding).
#       "hamming_exact" HammingExactIndex (exact packed-bit pre-filter).
#       "brute_force"   no index, exhaustive enumeration -- forces
#                       data_representation to behave as "raw" regardless
#                       of what was requested (no representation-preserving
#                       brute-force retrieval mode exists).
#
# Recommended: leave both at "auto" for production use; set
# data_representation="raw" (or candidate_backend="brute_force") only for a
# ground-truth/reference run.
_DATA_REPRESENTATION_ALIASES = {
    "auto": "auto",
    "raw": "raw", "none": "raw", "no_representation": "raw",
    "sketch_proj": "sketch_proj", "pearson_sketch": "sketch_proj", "pearson": "sketch_proj", "sketch": "sketch_proj",
    "sketch_concordance": "sketch_concordance", "concordance": "sketch_concordance",
    "sketch_multichannel": "sketch_multichannel",
    "distance_corr_sketch_multichannel": "sketch_multichannel", "dcor_sketch_multichannel": "sketch_multichannel",
    # (2026-09-17) StatStream digest -- see Sketches._sketches_dft / StatStreamGridIndex
    "sketch_dft": "sketch_dft", "dft": "sketch_dft", "statstream": "sketch_dft",
    # (2026-09-17) CorrJoin representation -- see Sketches._sketches_paa / CorrJoinDoubleFilterIndex
    "sketch_paa_svd": "sketch_paa_svd", "paa_svd": "sketch_paa_svd", "corrjoin": "sketch_paa_svd", "paa": "sketch_paa_svd",
}
_VALID_DATA_REPRESENTATIONS = {"auto", "raw", "sketch_proj", "sketch_concordance", "sketch_multichannel", "sketch_dft", "sketch_paa_svd"}
_CANDIDATE_BACKEND_AXIS_ALIASES = {
    "auto": "auto",
    "lsh_approx": "lsh_approx", "lsh_sign_dot": "lsh_approx", "lsh": "lsh_approx",
    "hamming_exact": "hamming_exact", "lsh_hamming_exact": "hamming_exact",
    "brute_force": "brute_force", "exhaustive": "brute_force", "true_brute_force": "brute_force", "unconditional": "brute_force",
    # (2026-09-17) ParCorr / Cole-Shasha-Zhao competitor arm -- see ParCorrGridIndex.
    "parcorr_grid": "parcorr_grid", "parcorr": "parcorr_grid", "csz": "parcorr_grid",
    "cole_shasha_zhao": "parcorr_grid", "sketch_grid": "parcorr_grid",
    "statstream_grid": "statstream_grid", "dft_grid": "statstream_grid",
    "corrjoin_double_filter": "corrjoin_double_filter", "corrjoin_grid": "corrjoin_double_filter", "double_filter": "corrjoin_double_filter",
    # (2026-09-18) ablation: sketch computed, no index, optional gates -- see AllPairsGateIndex
    "all_pairs": "all_pairs", "no_index": "all_pairs", "sketch_all_pairs": "all_pairs",
}
_VALID_CANDIDATE_BACKEND_AXIS = {"auto", "lsh_approx", "hamming_exact", "brute_force", "parcorr_grid", "statstream_grid", "corrjoin_double_filter", "all_pairs"}


def _resolve_data_representation(value, validation_metric):
    key = str(value if value not in (None, "") else "auto").strip().lower().replace("-", "_")
    key = _DATA_REPRESENTATION_ALIASES.get(key, key)
    if key not in _VALID_DATA_REPRESENTATIONS:
        raise ValueError(
            f"data_representation={value!r} is not recognized. Valid values: "
            f"{sorted(_VALID_DATA_REPRESENTATIONS)}."
        )
    if key != "auto":
        return key
    metric = _resolve_validation_metric(validation_metric)
    if metric == "pearson":
        return "sketch_proj"
    if metric in ("spearman", "kendall"):
        return "sketch_concordance"
    return "sketch_multichannel"


def _resolve_candidate_backend_axis(value, data_representation="auto"):
    """Resolves to "lsh_approx"/"hamming_exact"/"brute_force". "auto" means
    "brute_force" when data_representation is "raw" (nothing to index),
    else "lsh_approx" (the established default)."""
    key = str(value if value not in (None, "") else "auto").strip().lower().replace("-", "_")
    key = _CANDIDATE_BACKEND_AXIS_ALIASES.get(key, key)
    if key not in _VALID_CANDIDATE_BACKEND_AXIS:
        raise ValueError(
            f"candidate_backend={value!r} is not recognized. Valid values: "
            f"{sorted(_VALID_CANDIDATE_BACKEND_AXIS)}."
        )
    if key != "auto":
        return key
    return "brute_force" if data_representation == "raw" else "lsh_approx"


def _resolve_internal_dispatch(data_representation, candidate_backend, validation_metric):
    """Maps the resolved (data_representation, candidate_backend) pair to
    the internal dispatch key the rest of CorrTrack already understands.
    Returns (effective_candidate_backend, internal_dispatch_key):
    effective_candidate_backend is one of "lsh_approx"/"hamming_exact"/
    "brute_force"; internal_dispatch_key is one of "auto"/"lsh_hamming_exact"
    (sketch_proj), "incremental_concordance_multichannel" (sketch_
    concordance), "distance_corr_sketch_multichannel" (sketch_multichannel),
    or "brute_force" (raw, or candidate_backend="brute_force" -- always an
    unconditional, representation-discarding no-op)."""
    rep = _resolve_data_representation(data_representation, validation_metric)
    be = _resolve_candidate_backend_axis(candidate_backend, rep)

    if rep == "raw" and be != "brute_force":
        raise ValueError(
            "data_representation='raw' has no vector representation to index -- "
            f"candidate_backend must be 'auto' or 'brute_force', not {candidate_backend!r}."
        )
    if be == "brute_force":
        return be, "brute_force"
    if be == "all_pairs":
        return be, "all_pairs"

    if rep == "sketch_dft":
        if be in ("auto", "statstream_grid"):
            return "statstream_grid", "statstream_grid"
        if be != "brute_force":
            raise ValueError(
                "data_representation='sketch_dft' (StatStream digest) is indexed by "
                f"candidate_backend='statstream_grid' (or 'brute_force'), not {candidate_backend!r}."
            )
    if rep == "sketch_paa_svd":
        if be in ("auto", "corrjoin_double_filter"):
            return "corrjoin_double_filter", "corrjoin_double_filter"
        if be != "brute_force":
            raise ValueError(
                "data_representation='sketch_paa_svd' (CorrJoin) is indexed by "
                f"candidate_backend='corrjoin_double_filter' (or 'brute_force'), not {candidate_backend!r}."
            )
    if be == "corrjoin_double_filter" and rep != "sketch_paa_svd":
        raise ValueError(
            "candidate_backend='corrjoin_double_filter' (CorrJoin) needs data_representation='sketch_paa_svd', "
            f"not {rep!r}."
        )
    if be == "statstream_grid" and rep != "sketch_dft":
        raise ValueError(
            "candidate_backend='statstream_grid' (StatStream) needs data_representation='sketch_dft', "
            f"not {rep!r}."
        )
    if be == "parcorr_grid" and rep != "sketch_proj":
        raise ValueError(
            "candidate_backend='parcorr_grid' (ParCorr / Cole-Shasha-Zhao) indexes the random-"
            f"projection sketch and needs data_representation='sketch_proj', not {rep!r}."
        )
    if rep == "sketch_proj":
        if be == "parcorr_grid":
            return be, "parcorr_grid"
        return be, ("lsh_hamming_exact" if be == "hamming_exact" else "auto")
    if rep == "sketch_concordance":
        return be, "incremental_concordance_multichannel"
    if rep == "sketch_multichannel":
        return be, "distance_corr_sketch_multichannel"
    raise AssertionError(f"unreachable data_representation {rep!r}")  # pragma: no cover


_BLOCKED_INDEX_BACKENDS = {"sorted_arrays_bs"}
# (2026-07-06) InstinctIndex -- experimental approximate graph backend, NOT
