def _coerce_int_list(value, default=None, *, field_name="value"):
    if value is None or value == "":
        value = default
    if value is None:
        return []
    if isinstance(value, str):
        try:
            parsed = ast.literal_eval(value)
        except (SyntaxError, ValueError):
            parsed = value
        value = parsed
    if isinstance(value, (np.integer, int)):
        items = [int(value)]
    else:
        try:
            items = list(value)
        except TypeError:
            items = [value]

    out = []
    seen = set()
    for item in items:
        try:
            item_int = int(item)
        except (TypeError, ValueError):
            raise ValueError(f"{field_name} must contain positive integers.") from None
        if item_int <= 0:
            raise ValueError(f"{field_name} must contain positive integers.")
        if item_int not in seen:
            out.append(item_int)
            seen.add(item_int)
    return out


def _compute_base_cell_size(corr_threshold, n_vectors):
    if corr_threshold is None:
        return None
    n_vec = _to_float_safe(n_vectors)
    if n_vec is None or n_vec <= 0.0:
        return None
    try:
        return math.sqrt((1.0 - float(corr_threshold)) * 2.0) / math.sqrt(n_vec)
    except (ValueError, ZeroDivisionError):
        return None


def _resolve_cell_stretch(
    stretch_value,
    cell_size_value,
    corr_threshold,
    n_vectors,
    grid_dimension,
    default=1.0,
    full_vector_candidates=False,
):
    stretch = _to_float_safe(stretch_value)
    if stretch is not None and stretch > 0.0:
        return stretch

    size = _to_float_safe(cell_size_value)
    if size is None:
        return default

    base = _compute_base_cell_size(corr_threshold, n_vectors)
    n_vec = _to_float_safe(n_vectors)
    if base is None or base <= 0.0 or n_vec is None or n_vec <= 0.0:
        return default

    if full_vector_candidates:
        radius_scale = math.sqrt(n_vec)
    else:
        grid_dim = _to_float_safe(grid_dimension)
        if grid_dim is None or grid_dim <= 0.0:
            grid_dim = 1.0
        radius_scale = math.sqrt(grid_dim)

    if radius_scale <= 0.0:
        return default

    stretch = size / (base * radius_scale)
    if not math.isfinite(stretch) or stretch <= 0.0:
        return default
    return stretch


def _fast_corr_and_dist(x, y, return_stats=False):
    """Compute Pearson correlation and Euclidean distance without temporary arrays.

    When ``return_stats`` is True, also returns (n, mean_x, mean_y, var_x, var_y),
    where var_* are the summed squared deviations (n * variance).
    """
    if _cy_fast_corr_and_dist is not None:
        try:
            corr, dist, stats = _cy_fast_corr_and_dist(
                np.asarray(x, dtype=np.float64),
                np.asarray(y, dtype=np.float64),
            )
            if return_stats:
                return corr, dist, stats
            return corr, dist
        except Exception:
            pass
    x = np.asarray(x, dtype=np.float64)
    y = np.asarray(y, dtype=np.float64)

    n = x.size
    if n == 0:
        if return_stats:
            return np.nan, np.inf, (0, 0.0, 0.0, 0.0, 0.0)
        return np.nan, np.inf

    sx = float(x.sum(dtype=np.float64))
    sy = float(y.sum(dtype=np.float64))
    sum_xy = float(np.dot(x, y))
    sum_xx = float(np.dot(x, x))
    sum_yy = float(np.dot(y, y))

    mean_x = sx / n
    mean_y = sy / n
    var_x = sum_xx - (sx * sx) / n
    var_y = sum_yy - (sy * sy) / n
    var_x = max(var_x, 0.0)
    var_y = max(var_y, 0.0)

    denom = math.sqrt(var_x * var_y)

    if denom == 0.0:
        corr = np.nan
    else:
        cov = sum_xy - (sx * sy) / n
        corr = cov / denom if denom else np.nan
        if corr > 1.0:
            corr = 1.0
        elif corr < -1.0:
            corr = -1.0

    dist_sq = sum_xx + sum_yy - 2.0 * sum_xy
    dist = math.sqrt(max(dist_sq, 0.0))

    if return_stats:
        return corr, dist, (n, mean_x, mean_y, var_x, var_y)
    return corr, dist


def _metric_distance_from_corr(corr):
    if corr is None or not np.isfinite(corr):
        return np.inf
    return math.sqrt(max(2.0 * (1.0 - abs(float(corr))), 0.0))


def _passes_corr_threshold(corr, corr_threshold, neg_corr):
    if corr is None or np.isnan(corr):
        return False
    if neg_corr:
        return abs(float(corr)) >= corr_threshold
    return float(corr) >= corr_threshold


def _compute_series_dots(window_blocks, weights):
    kernel = os.environ.get("CORRTRACK_SKETCH_KERNEL")
    if kernel:
        kernel = kernel.strip().lower()
    else:
        kernel = "cython" if _cy_compute_series_dots is not None else "numpy"
    if kernel == "cython" and _cy_compute_series_dots is not None:
        try:
            wb = np.ascontiguousarray(window_blocks, dtype=np.float64)
            wt = np.ascontiguousarray(weights, dtype=np.float64)
            return _cy_compute_series_dots(wb, wt)
        except Exception:
            pass
    return np.einsum("sbw,bvw->sbv", window_blocks, weights, optimize=True)


def _is_near_constant_stats(var_sum, n, std_thresh=1e-3):
    if std_thresh is None:
        std_thresh = 1e-3
    if n <= 0:
        return True
    return var_sum <= (std_thresh ** 2) * n


def _is_structurally_spiked_stats(x, mean, var_sum, n, kurt_thresh=5.0, mu4_sum=None):
    if n < 4 or var_sum <= 0.0:
        return False

    if mu4_sum is None:
        if x is None:
            return False
        centered = np.asarray(x, dtype=np.float64) - mean
        mu4 = float(np.sum(centered ** 4))
    else:
        mu4 = float(mu4_sum)

    var = var_sum / n
    if var <= 0.0:
        return False
    kurt = (mu4 / n) / (var * var) - 3.0
    return kurt > kurt_thresh


# (2026-07-28) Non-Pearson validation metrics, ported from
# corrtrack_release_nonlinear for part 3 of the 2026-07-27(a) roadmap -- see
# docs/implementation_log.md's 2026-07-28 entries. Unlike that variant
# (whose own metric resolver has no "pearson" case at all, and validates
# EVERY metric including the linear one via pure-Python/scipy per pair),
# "pearson" is added here as a first-class option that stays on the
# existing fast Cython bulk-validation path unchanged -- only spearman/
# kendall/dist_corr route through the new per-row Python path below.
def _resolve_validation_metric(value=None):
    if value is None or value == "":
        return "pearson"
    metric = str(value).strip().lower().replace("-", "_")
    aliases = {
        "spearmanr": "spearman",
        "kendalltau": "kendall",
        "kendall_tau": "kendall",
        "distance_correlation": "dist_corr",
        "distance_corr": "dist_corr",
        "distcorr": "dist_corr",
        "dcor": "dist_corr",
        "linear": "pearson",
    }
    metric = aliases.get(metric, metric)
    if metric not in {"pearson", "spearman", "kendall", "dist_corr"}:
        raise ValueError("validation_metric must be 'pearson', 'spearman', 'kendall', or 'dist_corr'.")
    return metric


def _derive_candidate_tau(corr_threshold, validation_metric):
    # Maps corr_threshold (always expressed on the Pearson-like scale the
    # rest of CorrTrack's config uses) to the ordinal candidate-search gamma
    # (a cosine/sign-agreement threshold on the SAME scale ordinal_distance_
    # threshold expects) -- ported from corrtrack_release_nonlinear. Kendall
    # tau is already on a comparable [-1, 1] concordance scale so it passes
    # through unchanged; Spearman uses the standard bivariate-normal
    # Pearson<->Spearman relation rho_s = (2/pi) * arcsin(rho).
    metric = _resolve_validation_metric(validation_metric)
    threshold = _to_float_safe(corr_threshold)
    if threshold is None or not math.isfinite(threshold):
        threshold = 0.0
    threshold = max(-1.0, min(1.0, float(threshold)))
    if metric == "kendall":
        return threshold
    return (2.0 / math.pi) * math.asin(threshold)


def _distance_correlation_1d(x, y):
    # Naive O(w^2) distance correlation (Szekely/Rizzo/Bakirov) -- ported
    # as-is from corrtrack_release_nonlinear's global_ordinal_backend.py.
    # A known exact O(w log w) algorithm exists (Huo & Szekely 2016) but was
    # not part of this port; flagged as a real, not-yet-taken optimization
    # for whoever picks up the distance-correlation thread next.
    x_arr = np.asarray(x, dtype=np.float64).ravel()
    y_arr = np.asarray(y, dtype=np.float64).ravel()
    n = min(int(x_arr.size), int(y_arr.size))
    if n < 2:
        return np.nan
    x_arr = x_arr[:n]
    y_arr = y_arr[:n]
    mask = np.isfinite(x_arr) & np.isfinite(y_arr)
    x_arr = x_arr[mask]
    y_arr = y_arr[mask]
    n = int(x_arr.size)
    if n < 2:
        return np.nan

    a = np.abs(x_arr[:, None] - x_arr[None, :])
    b = np.abs(y_arr[:, None] - y_arr[None, :])
    a_centered = a - a.mean(axis=0, keepdims=True) - a.mean(axis=1, keepdims=True) + a.mean()
    b_centered = b - b.mean(axis=0, keepdims=True) - b.mean(axis=1, keepdims=True) + b.mean()

    dcov2 = float(np.mean(a_centered * b_centered))
    dvar_x = float(np.mean(a_centered * a_centered))
    dvar_y = float(np.mean(b_centered * b_centered))
    denom = math.sqrt(max(dvar_x, 0.0) * max(dvar_y, 0.0))
    if denom <= 0.0 or not math.isfinite(denom):
        return np.nan
    dcorr2 = max(dcov2, 0.0) / denom
    return math.sqrt(max(0.0, min(1.0, dcorr2)))


def _kendall_tau(x, y):
    """Exact Kendall's tau-b, matching scipy.stats.kendalltau's default
    variant. (2026-07-31) Cython-only, by explicit instruction ("I want no
    hotpaths in python whatsoever"): validation_metric="kendall" used to
    call scipy.stats.kendalltau directly from within the per-row Python
    validation loop -- full Python-level function-call overhead on every
    candidate, every step. Ported to candidate_kernels.kendall_tau_cy (the
    same Knight 1966 merge-sort inversion-counting algorithm scipy itself
    uses, in a tight nogil loop), verified bit-identical (~1e-13) against
    scipy.stats.kendalltau across 2000 random trials spanning heavy ties,
    monotonic-nonlinear, and independent data (see docs/implementation_
    log.md's 2026-07-31 entry). No Python fallback -- raises if the
    compiled extension is unavailable, matching this project's existing
    strict pattern for distance_corr_sketch_proxy/candidate_backend=
    "flat"/"lsh_sign_dot"."""
    if _cy_kendall_tau is None:
        raise RuntimeError(
            "validation_metric='kendall' requires the compiled candidate_kernels "
            "Cython extension (kendall_tau_cy); the Python/scipy fallback was "
            "removed by explicit instruction. Rebuild with "
            "`python3 setup_cython.py build_ext --inplace`."
        )
    return _cy_kendall_tau(
        np.ascontiguousarray(x, dtype=np.float64),
        np.ascontiguousarray(y, dtype=np.float64),
    )


def _spearman_rho(x, y):
    """Exact Spearman's rho (average-rank tie handling, then Pearson on
    ranks), matching scipy.stats.spearmanr. Same rationale/precedent as
    _kendall_tau above -- see candidate_kernels.spearman_rho_cy. No Python
    fallback -- raises if the compiled extension is unavailable."""
    if _cy_spearman_rho is None:
        raise RuntimeError(
            "validation_metric='spearman' requires the compiled candidate_kernels "
            "Cython extension (spearman_rho_cy); the Python/scipy fallback was "
            "removed by explicit instruction. Rebuild with "
            "`python3 setup_cython.py build_ext --inplace`."
        )
    return _cy_spearman_rho(
        np.ascontiguousarray(x, dtype=np.float64),
        np.ascontiguousarray(y, dtype=np.float64),
    )


def _dist_corr_fast(x, y):
    """Exact O(n log n) univariate distance correlation (dist_corr_algorithm
    ="fast"), matching huo_szekely_distance_correlation.distance_
    correlation_1d_fast's own double-centering identity. (2026-07-31)
    Cython-only, by the same explicit instruction as _kendall_tau/
    _spearman_rho above: the pure-Python version's cross-term sweep drove 4
    pure-Python _FenwickTree objects through an interpreted per-element
    loop -- ported to candidate_kernels.distance_correlation_1d_fast_cy
    (flat C Fenwick buffers in a nogil loop), verified bit-identical
    (~1e-14) against both the pure-Python "fast" reference and the naive
    O(w^2) estimator across 2000 trials (ties, linear, nonlinear -- see
    docs/implementation_log.md's 2026-07-31 entry). No Python fallback --
    raises if the compiled extension is unavailable."""
    if _cy_distance_correlation_1d_fast is None:
        raise RuntimeError(
            "dist_corr_algorithm='fast' requires the compiled candidate_kernels "
            "Cython extension (distance_correlation_1d_fast_cy); the Python "
            "fallback was removed by explicit instruction. Rebuild with "
            "`python3 setup_cython.py build_ext --inplace`."
        )
    return _cy_distance_correlation_1d_fast(
        np.ascontiguousarray(x, dtype=np.float64),
        np.ascontiguousarray(y, dtype=np.float64),
    )


def _metric_corr_and_dist(x, y, metric="pearson", return_stats=False, dist_corr_algorithm="naive"):
    metric = _resolve_validation_metric(metric)
    linear_corr, _raw_dist, stats = _fast_corr_and_dist(x, y, return_stats=True)

    if metric == "pearson":
        corr = linear_corr
    else:
        x_arr = np.asarray(x, dtype=np.float64)
        y_arr = np.asarray(y, dtype=np.float64)
        if metric == "dist_corr":
            # (2026-07-29) "fast" is Huo & Szekely-style O(w log w) --
            # EXACT (not approximate, unlike Xiao's online Spearman/Kendall),
            # verified against this naive O(w^2) estimator on 500 random
            # trials (max diff ~1e-14, see huo_szekely_distance_correlation.py's
            # module docstring). Kept opt-in rather than the new default:
            # measured directly, the naive numpy-vectorized version is
            # actually FASTER below ~w=200 (a pure-Python Fenwick-tree loop
            # loses to numpy's O(w^2) vectorization at small w); "fast" only
            # wins asymptotically at larger window sizes. Default stays
            # "naive" so no behavior/performance regression at this
            # project's typical window sizes without an explicit opt-in.
            if dist_corr_algorithm == "fast":
                corr = _dist_corr_fast(x_arr, y_arr)
            else:
                corr = _distance_correlation_1d(x_arr, y_arr)
        else:
            if metric == "spearman":
                corr = _spearman_rho(x_arr, y_arr)
            else:
                corr = _kendall_tau(x_arr, y_arr)
            try:
                corr = float(corr)
            except (TypeError, ValueError):
                corr = np.nan
    dist = _metric_distance_from_corr(corr)
    if return_stats:
        return corr, dist, stats
    return corr, dist


def _sketch_worker(payload):
    """Execute a sketch node update."""
    corrtrack, node_index, node_new, ids_subset, verbose, testing = payload
    sketch_node = corrtrack.sketch_nodes[node_index]
    sketch_node._sid_lookup = corrtrack.series_ids
    sketch_node._profile_callback = corrtrack._profile_add if getattr(corrtrack, "profile_enabled", False) else None
    sketches, partitions = sketch_node.run(
        node_new,
        ids_subset,
        verbose=verbose,
        testing=testing,
        distribute=False,
    )
    return node_index, sketch_node, sketches, partitions


def _sketch_multi_worker(payload):
    """Execute one sketch node update and derive sketches for several sizes.

    (2026-07-28) Ported from corrtrack_release_multiwinsizes for
    CorrTrackMultiWindow -- see docs/implementation_log.md's 2026-07-28
    entries.
    """
    corrtrack, node_index, node_new, ids_subset, window_sizes, verbose, testing = payload
    sketch_node = corrtrack.sketch_nodes[node_index]
    sketch_node._sid_lookup = corrtrack.series_ids
    sketch_node._profile_callback = corrtrack._profile_add if getattr(corrtrack, "profile_enabled", False) else None
    sketches, partitions = sketch_node.run_multi(
        node_new,
        ids_subset,
        window_sizes,
        verbose=verbose,
        testing=testing,
    )
    return node_index, sketch_node, sketches, partitions


def _grid_worker(payload):
    """Execute a grid node run."""
    corrtrack, grid_index, n_ids, verbose, testing = payload[:5]
    try:
        numeric_rows = bool(payload[5])
    except (IndexError, TypeError):
        numeric_rows = True
    grid_node = corrtrack.grid_nodes[grid_index]
    result = grid_node.run(n_ids, verbose=verbose, testing=testing, numeric_rows=numeric_rows)
    return grid_index, grid_node, result


def _bf_worker(payload):
    """Execute brute-force candidate generation for a shard."""
    if len(payload) >= 8:
        index, bf_node, window_step, ids, verbose, testing, ref_ids, numeric_rows = payload[:8]
    else:
        index, bf_node, window_step, ids, verbose, testing, ref_ids = payload
        numeric_rows = True
    result = bf_node.run(
        window_step,
        ids,
        verbose=verbose,
        testing=testing,
        ref_ids=ref_ids,
        numeric_rows=bool(numeric_rows),
    )
    return index, bf_node, result


def _compute_nonconst_mask(data, window_size, std_thresh=None):
    csum = np.cumsum(data, axis=1, dtype=np.float64)
    csum = np.pad(csum, ((0, 0), (1, 0)), mode="constant")
    csum_sq = np.cumsum(data * data, axis=1, dtype=np.float64)
    csum_sq = np.pad(csum_sq, ((0, 0), (1, 0)), mode="constant")
    window_sums = csum[:, window_size:] - csum[:, :-window_size]
    window_sums_sq = csum_sq[:, window_size:] - csum_sq[:, :-window_size]
    var_sum = window_sums_sq - (window_sums * window_sums) / window_size
    if std_thresh is None:
        std_thresh = 1e-3
    threshold = (float(std_thresh) ** 2) * window_size
    return np.maximum(var_sum, 0.0) > threshold


def _enumerate_candidate_rows(
    data,
    window_index,
    ref_indices,
    window_size,
    window_step,
    mask=None,
    std_thresh=None,
    shard_start=None,
    shard_end=None,
):
    if _cy_enumerate_candidate_rows is not None and mask is None:
        std_val = 1e-3 if std_thresh is None else float(std_thresh)
        shard_start_val = -1 if shard_start is None else int(shard_start)
        shard_end_val = -1 if shard_end is None else int(shard_end)
        ref_idx_arr = np.asarray(list(ref_indices), dtype=np.int64)
        if ref_idx_arr.size == 0:
            return None
        return _cy_enumerate_candidate_rows(
            np.ascontiguousarray(data, dtype=np.float64),
            np.ascontiguousarray(window_index, dtype=np.int64),
            ref_idx_arr,
            int(window_size),
            int(window_step),
            std_val,
            shard_start_val,
            shard_end_val,
        )

    data = np.asarray(data)
    n_series, n_cols = data.shape
    window_count = n_cols - window_size + 1
    if window_count <= 0:
        return None

    working_mask = mask
    if working_mask is not None:
        working_mask = np.asarray(working_mask, dtype=bool)
        working_mask = working_mask.reshape(n_series, window_count)
    else:
        working_mask = _compute_nonconst_mask(
            data.astype(np.float64, copy=False),
            window_size,
            std_thresh=std_thresh,
        )

    if working_mask.size == 0:
        return None

    step_mask = (np.arange(window_count) % max(1, window_step)) == 0
    valid_mask = working_mask & step_mask
    last_idx = window_count - 1
    seeds_mask = valid_mask[:, last_idx]
    if not np.any(seeds_mask):
        return None

    valid_k_all, valid_j_all = np.nonzero(valid_mask)
    if valid_k_all.size == 0:
        return None

    j_start_times = window_index[valid_j_all].astype(np.int64, copy=False)
    curr_start = int(window_index[last_idx])
    rows_accum = []

    for s_idx in ref_indices:
        if s_idx >= n_series or not seeds_mask[s_idx]:
            continue

        mask_sel = np.ones(valid_k_all.shape[0], dtype=bool)
        mask_sel &= ~((valid_k_all <= s_idx) & (valid_j_all == last_idx))
        if not mask_sel.any():
            continue

        indices = np.nonzero(mask_sel)[0]
        k_sel = valid_k_all[indices]
        if shard_start is not None and shard_end is not None:
            shard_mask = (k_sel >= shard_start) & (k_sel < shard_end)
            if not shard_mask.any():
                continue
            indices = indices[shard_mask]
            k_sel = k_sel[shard_mask]
        if indices.size == 0:
            continue

        rows_accum.append(
            np.column_stack(
                [
                    np.full(indices.size, s_idx, dtype=np.int64),
                    valid_k_all[indices].astype(np.int64, copy=False),
                    np.full(indices.size, curr_start, dtype=np.int64),
                    j_start_times[indices],
                    np.full(indices.size, window_size, dtype=np.int64),
                ]
            )
        )

    if not rows_accum:
        return None

    return np.vstack(rows_accum)


def _normalize_bf_key(pair):
    id1, id2, t1, t2, w = pair

    if id1 == id2:
        return (id1, id2, max(t1, t2), min(t1, t2), w)

    if t1 == t2:
        return tuple(sorted([id1, id2])) + (t1, t2, w)

    if t1 < t2:
        return (id2, id1, t2, t1, w)
    return (id1, id2, t1, t2, w)


def _canonicalize_rows(rows):
    """Vectorized replica of _normalize_bf_key for a batch of numeric candidate rows.

    `rows` is an int array shaped (N, 5) with columns [s1, s2, t1, t2, w] (s1/s2 are
    the integer series indices, t1/t2 absolute window start times). Returns a NEW (N, 5)
    array where each row is put in the same canonical orientation _normalize_bf_key
    produces for the scalar tuple: the later-start side first, id-sorted on ties.

    The four scalar branches collapse to a single predicate: swap (s1,s2) and (t1,t2)
    together iff  t1 < t2  OR  (t1 == t2 AND s1 > s2).  Verified case-by-case against
    _normalize_bf_key including the s1==s2 (autocorrelation) and t1==t2 (synchronous)
    cases -- see test_canonicalize_rows_matches_scalar_normalize_bf_key.
    """
    rows = np.ascontiguousarray(np.asarray(rows, dtype=np.int64).reshape((-1, 5)))
    if rows.shape[0] == 0:
        return rows
    s1 = rows[:, 0]
    s2 = rows[:, 1]
    t1 = rows[:, 2]
    t2 = rows[:, 3]
    swap = (t1 < t2) | ((t1 == t2) & (s1 > s2))
    out = rows.copy()
    if swap.any():
        out[swap] = rows[swap][:, [1, 0, 3, 2, 4]]
    return out


def _proxy_canonical_pair_rows(rows):
    """(2026-09-20) Canonical order of proxy pair rows [sidx1, sidx2, t1, t2] (int64), the numeric twin of
    CorrTrack_optimize._normalize_window_pair_key: the later window first; at equal times the smaller
    series index first; for a series paired with itself the later time first."""
    r = np.array(rows, dtype=np.int64, copy=True).reshape((-1, 4))
    if r.shape[0] == 0:
        return r
    swap = (r[:, 2] < r[:, 3]) | ((r[:, 2] == r[:, 3]) & (r[:, 0] > r[:, 1]))
    if np.any(swap):
        sw = r[swap]
        r[swap, 0], r[swap, 1], r[swap, 2], r[swap, 3] = sw[:, 1], sw[:, 0], sw[:, 3], sw[:, 2]
    return r


def _proxy_rows_as_keys(rows):
    """32-byte void keys of canonical proxy pair rows (sortable, comparable; searchsorted-friendly)."""
    r = np.ascontiguousarray(np.asarray(rows, dtype=np.int64).reshape((-1, 4)))
    return r.view(np.dtype((np.void, 32))).reshape(-1)


def _rows_as_void_keys(rows):
    """View an (N, 5) int64 rows array as a 1-D array of opaque per-row keys, so numpy
    set operations (np.isin / np.unique) treat each whole row as one hashable element."""
    rows = np.ascontiguousarray(np.asarray(rows, dtype=np.int64).reshape((-1, 5)))
    return rows.view(np.dtype((np.void, rows.dtype.itemsize * rows.shape[1]))).ravel()


class ArrayBackedPartition(dict):
    """(2026-09-24) A partition dict that also carries the arrays it was built from.

    `Sketches.partition_sketches` computes the sketch matrix, the series indices, the times, the window
    sizes and the constant mask as arrays, then materializes a {window_key: (vector, is_const, 0.0)} dict
    from them; `Candidates._input_tree_lsh_batch` used to walk that dict back into the same arrays one
    window at a time (a per-window np.asarray, a ravel, eight list appends and a dict lookup), which the
    2026-09-24 profile found to be the single largest Python cost of the candidate stage. Carrying the
    arrays on the dict lets the insert use them directly while every other consumer keeps seeing a plain
    dict, so no call site and no behaviour changes. `arrays` is (keys, matrix, sid_idx, time, w, is_const)
    or None when the partition was not built this way (the merge and copy paths below), in which case the
    insert falls back to the original loop.
    """

    __slots__ = ("arrays", "win_slots", "min_time")

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.arrays = None
        self.win_slots = None      # the window-registry slots this partition's windows were given
        self.min_time = None       # the smallest window start in it, for the index's expiry cutoff


class NumericCorrelatedFlags:
    """(2026-09-10) The `corr_flags` return of a recall_by_window pass, in numeric form:
    the correlated set as (rows (N,5), corrs (N,) float64). `len()` is the number of
    correlated windows (same as the old string dict's len); `.correlated_rows()` and tuple
    unpacking give (rows, corrs), so `CorrTrack.compute_metrics_bf` consumes it directly
    with no per-key Python normalization.

    (2026-09-11) `rows`' dtype follows whatever integer dtype it was constructed with
    (int32 in the common case -- `CorrTrack.correlated_rows()`'s own accumulator storage,
    see its note) instead of always force-upcasting to int64. Found necessary by a real
    OOM directly caused by the OLD unconditional upcast here: it undid
    `correlated_rows()`'s own int32 memory fix the moment this wrapper was constructed
    around it (`execute_corrtrack_pass`'s `NumericCorrelatedFlags(*corrtrack.
    correlated_rows())`), on the SAME memory-constrained machine. Safe for the same reason
    as `correlated_rows()` itself: `CorrTrack.compute_metrics_bf`/`_as_row_corr_pair`
    already re-cast to int64 themselves when they actually need it -- this wrapper is
    usually just a transient carrier between a run and that comparison. Non-integer input
    (a plain list of tuples, say) still normalizes to int64, matching the old behavior."""

    __slots__ = ("rows", "corrs")

    def __init__(self, rows, corrs):
        rows_arr = np.asarray(rows)
        if rows_arr.dtype.kind not in ("i", "u"):
            rows_arr = rows_arr.astype(np.int64)
        self.rows = np.ascontiguousarray(rows_arr.reshape((-1, 5)))
        c = np.ascontiguousarray(np.asarray(corrs, dtype=np.float64).reshape((-1,)))
        if c.shape[0] != self.rows.shape[0]:
            c = np.ones(self.rows.shape[0], dtype=np.float64)
        self.corrs = c

    def __len__(self):
        return int(self.rows.shape[0])

    def __bool__(self):
        return self.rows.shape[0] > 0

    def correlated_rows(self):
        return self.rows, self.corrs

    def __iter__(self):
        return iter((self.rows, self.corrs))


def _normalize_window_metric_key(id1, id2, t1, t2, window_size):
    return _normalize_bf_key((id1, id2, t1, t2, window_size))


def _normalize_pair_lag_key(id1, id2, lag):
    ids = tuple(sorted((id1, id2)))
    return ids + (lag,)


def _marker_to_label(marker):
    if marker == 1:
        return "into"
    if marker == -1:
        return "out_of"
    if marker == 0:
        return "changed_sign"
    return str(marker)


def _label_to_marker(label):
    if label == "into":
        return 1
    if label == "out_of":
        return -1
    if label == "changed_sign":
        return 0
    try:
        return int(label)
    except (TypeError, ValueError):
        return 0


def _to_sortable_time_value(value):
    if isinstance(value, np.datetime64):
        if np.isnat(value):
            return ""
        return str(value.astype("datetime64[ns]"))
    if isinstance(value, (datetime.datetime, datetime.date)):
        return str(np.datetime64(value))
    if isinstance(value, (np.integer, int)):
        return int(value)
    if isinstance(value, (np.floating, float)):
        if math.isnan(value):
            return ""
        return float(value)
    return str(value)


def _window_sort_key(pair, window_size):
    id1, id2, t1, t2 = pair
    norm = _normalize_window_metric_key(id1, id2, t1, t2, window_size)
    return (
        str(norm[0]),
        str(norm[1]),
        _to_sortable_time_value(norm[2]),
        _to_sortable_time_value(norm[3]),
    )


def _status_sort_key(row):
    id1, id2, lag, t1, t2, _duration, _sign = row
    norm = _normalize_pair_lag_key(id1, id2, lag)
    return (
        str(norm[0]),
        str(norm[1]),
        _to_sortable_time_value(norm[2]),
        _to_sortable_time_value(t1),
        _to_sortable_time_value(t2),
    )


def _anomaly_sort_key(row):
    id1, id2, lag, time_val, marker = row
    norm = _normalize_pair_lag_key(id1, id2, lag)
    return (
        str(norm[0]),
        str(norm[1]),
        _to_sortable_time_value(norm[2]),
        _to_sortable_time_value(time_val),
        int(marker),
    )


def _maxlag_sort_key(key):
    id1, id2, t1_idx = key
    return (str(id1), str(id2), _to_sortable_time_value(t1_idx))


def _compute_total_time_from_record(record):
    try:
        n_w = int(float(record.get("n_w", 0) or 0))
        window_size = int(float(record.get("window_size", 0) or 0))
        window_step = int(float(record.get("window_step", 0) or 0))
    except (TypeError, ValueError):
        return 0
    if n_w <= 0 or window_size <= 0 or window_step <= 0:
        return 0
    return ((n_w - 1) * window_step) + window_size


def _intervals_total_length(intervals):
    total = 0
    for start, end in intervals:
        total += max(int(end) - int(start), 0)
    return total


def _intervals_overlap_length(lhs, rhs):
    i = j = 0
    overlap = 0
    while i < len(lhs) and j < len(rhs):
        start = max(int(lhs[i][0]), int(rhs[j][0]))
        end = min(int(lhs[i][1]), int(rhs[j][1]))
        if end > start:
            overlap += end - start
        if int(lhs[i][1]) <= int(rhs[j][1]):
            i += 1
        else:
            j += 1
    return overlap


def _welford_update(count, mean, m2, value):
    count += 1
    delta = value - mean
    mean += delta / count
    delta2 = value - mean
    m2 += delta * delta2
    return count, mean, m2


def _safe_prec_recall_from_counts(tp, pred_total, gt_total):
    precision = tp / pred_total if pred_total > 0 else 0.0
    recall = tp / gt_total if gt_total > 0 else 0.0
    return precision, recall


def _signed_precision_from_ambiguous_fp(tp_same_sign, tp_opposite_sign, pred_total):
    denom = max(int(pred_total or 0) - int(tp_opposite_sign or 0), 0)
    return int(tp_same_sign or 0) / denom if denom > 0 else 0.0


def _empty_stream_metrics(include_sign=True):
    metrics = {
        "precision": 0.0,
        "recall": 0.0,
        "specificity": 0.0,
        "f1_score": 0.0,
        "aucroc": float("nan"),
        "pr_auc": float("nan"),
        "recall_min": None,
    }
    if include_sign:
        metrics.update({
            "precision_pos": 0.0,
            "recall_pos": 0.0,
            "f1_score_pos": 0.0,
            "precision_neg": 0.0,
            "recall_neg": 0.0,
            "f1_score_neg": 0.0,
        })
    return metrics


def _current_candidate_anchor(corrtrack):
    window_index = getattr(corrtrack, "window_index", None)
    window_data = getattr(corrtrack, "window_data", None)
    window_size = getattr(corrtrack, "window_size", None)
    if window_index is None or window_data is None or window_size is None:
        return None
    try:
        window_count = int(window_data.shape[1]) - int(window_size) + 1
    except (AttributeError, TypeError, ValueError):
        return None
    if window_count <= 0 or len(window_index) < window_count:
        return None
    try:
        return int(window_index[window_count - 1])
    except (TypeError, ValueError, IndexError):
        return None


class _OptimizerBFWindowReferenceWriter:
    def __init__(self, csv_path, window_size):
        self.csv_path = csv_path
        self.window_size = window_size
        os.makedirs(os.path.dirname(csv_path) or ".", exist_ok=True)
        self._handle = open(csv_path, "w", newline="")
        self._writer = csv.writer(self._handle, delimiter=CSV_DELIMITER)
        self._writer.writerow(["id1", "id2", "time1_idx", "time2_idx", "sign"])
        self.gt_total = 0
        self.gt_pos = 0
        self.gt_neg = 0

    def observe(self, corrtrack):
        validated = getattr(corrtrack, "_validated_step", None) or {}
        if not validated:
            return
        rows = []
        for pair, corr in validated.items():
            norm = _normalize_window_metric_key(pair[0], pair[1], pair[2], pair[3], pair[4])
            sign = 1 if float(corr) > 0 else -1
            rows.append((str(norm[0]), str(norm[1]), int(norm[2]), int(norm[3]), int(sign)))
        rows.sort(key=lambda row: (row[2], row[0], row[1], row[3]))
        self._writer.writerows(rows)
        self.gt_total += len(rows)
        for row in rows:
            if row[4] > 0:
                self.gt_pos += 1
            else:
                self.gt_neg += 1

    def close(self):
        handle = getattr(self, "_handle", None)
        if handle is None:
            return
        try:
            handle.close()
        finally:
            self._handle = None


class _OptimizerOnlineWindowMetrics:
    def __init__(
        self,
        reference_csv,
        window_size,
        gt_total,
        gt_pos,
        gt_neg,
        total_pairs_bf=None,
        pair_min_dist=None,
    ):
        self.reference_csv = reference_csv
        self.window_size = window_size
        self.gt_total = int(gt_total or 0)
        self.gt_pos = int(gt_pos or 0)
        self.gt_neg = int(gt_neg or 0)
        try:
            self.total_pairs_bf = int(total_pairs_bf) if total_pairs_bf is not None else None
        except (TypeError, ValueError):
            self.total_pairs_bf = None
        self.recall_min_key = None
        if pair_min_dist is not None and isinstance(pair_min_dist, tuple) and len(pair_min_dist) >= 5:
            self.recall_min_key = _normalize_window_metric_key(
                pair_min_dist[0],
                pair_min_dist[1],
                pair_min_dist[2],
                pair_min_dist[3],
                pair_min_dist[4],
            )
        self.recall_min_hit = False
        self.pred_total = 0
        self.tp = 0
        self.tp_pos = 0
        self.tp_neg = 0
        self._file = open(reference_csv, newline="")
        self._reader = csv.DictReader(self._file, delimiter=_detect_csv_delimiter(reference_csv, default=CSV_DELIMITER))
        self._next_row = next(self._reader, None)

    @staticmethod
    def _parse_int(value):
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    def _load_group(self, anchor):
        group = {}
        while self._next_row is not None:
            row_anchor = self._parse_int(self._next_row.get("time1_idx"))
            if row_anchor is None:
                self._next_row = next(self._reader, None)
                continue
            if row_anchor < anchor:
                self._next_row = next(self._reader, None)
                continue
            if row_anchor > anchor:
                break
            id1 = self._next_row.get("id1")
            id2 = self._next_row.get("id2")
            time2 = self._parse_int(self._next_row.get("time2_idx"))
            sign = self._parse_int(self._next_row.get("sign"))
            if id1 is not None and id2 is not None and time2 is not None and sign is not None:
                group[(id1, id2, row_anchor, time2, self.window_size)] = sign
            self._next_row = next(self._reader, None)
        return group

    def observe(self, corrtrack):
        anchor = _current_candidate_anchor(corrtrack)
        if anchor is None:
            return
        gt_group = self._load_group(anchor)
        predicted = set()
        for pair in getattr(corrtrack, "candidates", {}) or {}:
            if not isinstance(pair, tuple) or len(pair) < 5:
                continue
            predicted.add(_normalize_window_metric_key(pair[0], pair[1], pair[2], pair[3], pair[4]))
        self.pred_total += len(predicted)
        if self.recall_min_key is not None and self.recall_min_key in predicted:
            self.recall_min_hit = True
        for key in predicted:
            sign = gt_group.get(key)
            if sign is None:
                continue
            self.tp += 1
            if sign > 0:
                self.tp_pos += 1
            else:
                self.tp_neg += 1

    def metrics(self):
        metrics = _empty_stream_metrics(include_sign=True)
        precision, recall = _safe_prec_recall_from_counts(self.tp, self.pred_total, self.gt_total)
        f1 = 2 * precision * recall / (precision + recall) if (precision + recall) else 0.0
        recall_pos = self.tp_pos / self.gt_pos if self.gt_pos > 0 else 0.0
        recall_neg = self.tp_neg / self.gt_neg if self.gt_neg > 0 else 0.0
        precision_pos = _signed_precision_from_ambiguous_fp(self.tp_pos, self.tp_neg, self.pred_total)
        precision_neg = _signed_precision_from_ambiguous_fp(self.tp_neg, self.tp_pos, self.pred_total)
        f1_pos = 2 * precision_pos * recall_pos / (precision_pos + recall_pos) if (precision_pos + recall_pos) else 0.0
        f1_neg = 2 * precision_neg * recall_neg / (precision_neg + recall_neg) if (precision_neg + recall_neg) else 0.0
        specificity = 0.0
        if self.total_pairs_bf is not None:
            negatives = max(self.total_pairs_bf - self.gt_total, 0)
            if negatives > 0:
                fp = max(self.pred_total - self.tp, 0)
                tn = max(negatives - fp, 0)
                specificity = tn / negatives
        metrics.update(
            {
                "precision": precision,
                "recall": recall,
                "specificity": specificity,
                "f1_score": f1,
                "precision_pos": precision_pos,
                "recall_pos": recall_pos,
                "f1_score_pos": f1_pos,
                "precision_neg": precision_neg,
                "recall_neg": recall_neg,
                "f1_score_neg": f1_neg,
                "recall_min": None if self.recall_min_key is None else int(self.recall_min_hit),
                "aucroc": float("nan"),
                "pr_auc": float("nan"),
            }
        )
        return metrics

    def close(self):
        handle = getattr(self, "_file", None)
        if handle is None:
            return
        try:
            handle.close()
        finally:
            self._file = None
            self._reader = None
            self._next_row = None


def _corr_validation_batch_worker(payload):
    """Validate a batch of candidate pairs.

    payload keys (current shape, built by CorrTrack._iter_validation_payloads):
      - pairs, rows ([s1, s2, t1, t2, w] int64 array), data, base_index
      - corr_threshold, neg_corr, corr_val
      - optionally current_window_sums/_sq/_cu/_qu + current_window_size
        ("point 1": lets validate_corr_rows skip re-accumulating whichever
        side of a pair is the just-arrived current window, entirely inside
        its own nogil loop -- see docs/implementation_log.md)

    Legacy payload keys (items: list of {"pair","x","y"} dicts) are also
    supported, for any caller not using the rows-based shape above.
    Returns list of tuples (pair, is_corr, corr, dist, is_constant, is_spiked)
    """
    corr_threshold = payload["corr_threshold"]
    neg_corr = payload["neg_corr"]
    corr_val = payload.get("corr_val", True)
    std_thresh = 1e-3

    rows = payload.get("rows")
    if rows is not None:
        pairs = payload.get("pairs") or []
        if not corr_val:
            return [(pair, True, 1.0, 0.0, False, False) for pair in pairs]
        if not pairs:
            return []
        data = payload["data"]
        base_index = payload["base_index"]
        if _cy_validate_corr_rows is not None:
            try:
                accepted_mask, corrs, dists, consts, spikes = _cy_validate_corr_rows(
                    np.ascontiguousarray(data, dtype=np.float64),
                    rows,
                    int(base_index),
                    float(corr_threshold),
                    bool(neg_corr),
                    std_thresh,
                    5.0,
                    current_window_sums=payload.get("current_window_sums"),
                    current_window_sums_sq=payload.get("current_window_sums_sq"),
                    current_window_sums_cu=payload.get("current_window_sums_cu"),
                    current_window_sums_qu=payload.get("current_window_sums_qu"),
                    current_window_size=payload.get("current_window_size", -1),
                )
                return [
                    (
                        pair,
                        bool(accepted_mask[i]),
                        float(corrs[i]),
                        float(dists[i]),
                        bool(consts[i]),
                        bool(spikes[i]),
                    )
                    for i, pair in enumerate(pairs)
                ]
            except Exception:
                pass

        results = []
        for i, pair in enumerate(pairs):
            s1, s2, t1, t2, w = (int(v) for v in rows[i])
            start1 = t1 - base_index
            start2 = t2 - base_index
            x = data[s1, start1:start1 + w]
            y = data[s2, start2:start2 + w]
            pair_corr, pair_dist, stats = _fast_corr_and_dist(x, y, return_stats=True)
            n, mean_x, mean_y, var_x, var_y = stats
            if _is_near_constant_stats(var_x, n, std_thresh=std_thresh) or _is_near_constant_stats(var_y, n, std_thresh=std_thresh):
                results.append((pair, False, np.nan, np.inf, True, False))
                continue
            if (
                _is_structurally_spiked_stats(x, mean_x, var_x, n, kurt_thresh=5.0)
                or _is_structurally_spiked_stats(y, mean_y, var_y, n, kurt_thresh=5.0)
            ):
                results.append((pair, False, np.nan, np.inf, False, True))
                continue
            is_correlated = _passes_corr_threshold(pair_corr, corr_threshold, neg_corr)
            results.append((pair, is_correlated, pair_corr, pair_dist, False, False))
        return results

    items = payload.get("items")
    if items is None:
        return []

    if not corr_val:
        return [
            (item["pair"], True, 1.0, 0.0, False, False)
            for item in items
        ]
    results = []

    if _cy_validate_corr_batch is not None:
        try:
            x_batch = np.asarray([item["x"] for item in items], dtype=np.float64)
            y_batch = np.asarray([item["y"] for item in items], dtype=np.float64)
            if x_batch.ndim == 2 and y_batch.shape == x_batch.shape:
                eff_std_thresh = float(std_thresh) if std_thresh is not None else 1e-3
                batch_results = _cy_validate_corr_batch(
                    x_batch,
                    y_batch,
                    float(corr_threshold),
                    bool(neg_corr),
                    eff_std_thresh,
                )
                for item, entry in zip(items, batch_results):
                    is_correlated, pair_corr, pair_dist, is_const, is_spiked = entry
                    results.append((item["pair"], is_correlated, pair_corr, pair_dist, is_const, is_spiked))
                return results
        except Exception:
            results = []

    try:
        for item in items:
            pair = item["pair"]

            x = item["x"]
            y = item["y"]

            pair_corr, pair_dist, stats = _fast_corr_and_dist(x, y, return_stats=True)
            n, mean_x, mean_y, var_x, var_y = stats

            if _is_near_constant_stats(var_x, n, std_thresh=std_thresh) or _is_near_constant_stats(var_y, n, std_thresh=std_thresh):
                results.append((pair, False, np.nan, np.inf, True, False))
                continue

            if (
                _is_structurally_spiked_stats(x, mean_x, var_x, n, kurt_thresh=5.0)
                or _is_structurally_spiked_stats(y, mean_y, var_y, n, kurt_thresh=5.0)
            ):
                results.append((pair, False, np.nan, np.inf, False, True))
                continue

            is_correlated = _passes_corr_threshold(pair_corr, corr_threshold, neg_corr)

            results.append((pair, is_correlated, pair_corr, pair_dist, False, False))

        return results
    finally:
        pass
